function isDirectReferenceUrl(value: string) {
  return /^https?:\/\//i.test(value) || /^data:image\//i.test(value)
}

function isProjectAssetStoragePath(value: string) {
  return /^generated\//i.test(value) || /^uploads\//i.test(value) || /^project-assets\//i.test(value)
}

function mimeTypeForStoragePath(storagePath: string) {
  const lower = storagePath.toLowerCase()
  if (lower.endsWith('.webp')) return 'image/webp'
  if (lower.endsWith('.jpg') || lower.endsWith('.jpeg')) return 'image/jpeg'
  if (lower.endsWith('.gif')) return 'image/gif'
  if (lower.endsWith('.mp4')) return 'video/mp4'
  return 'image/png'
}

function referenceValuePriority(value: string) {
  const lower = value.toLowerCase()
  if (lower.includes('entity-reference-sheet') || lower.includes('entity_reference_sheet')) return 0
  if (lower.includes('reference-sheet') || lower.includes('reference_sheet')) return 1
  if (lower.includes('world_icon') || lower.includes('world-icons')) return 8
  if (lower.includes('icon')) return 7
  return 3
}

function sortReferenceValues(values: string[]) {
  return [...new Set(values.map((value) => value.trim()).filter(Boolean))]
    .sort((left, right) => {
      const priorityDelta = referenceValuePriority(left) - referenceValuePriority(right)
      if (priorityDelta !== 0) return priorityDelta
      return left.localeCompare(right)
    })
}

function selectedReferenceVariantAssetKeyForEntity(entity: Record<string, unknown>) {
  const metadata = asRecord(entity.metadata)
  return readText(metadata.selectedReferenceVariantAssetKey)
    || readText(entity.selectedReferenceVariantAssetKey)
}

function sortReferenceValuesWithPrimary(values: string[], primaryAssetKey = '') {
  const primary = primaryAssetKey.trim()
  const sorted = sortReferenceValues(values)
  if (!primary) return sorted
  return [primary, ...sorted.filter((value) => value !== primary)]
}

function entityAssetKeys(entity: Record<string, unknown>, assets: Record<string, unknown>[]) {
  const metadata = asRecord(entity.metadata)
  const referenceVariants = Array.isArray(metadata.referenceVariants)
    ? metadata.referenceVariants.map(asRecord)
    : Array.isArray(entity.referenceVariants)
      ? entity.referenceVariants.map(asRecord)
      : []
  const selectedReferenceVariantAssetKey = selectedReferenceVariantAssetKeyForEntity(entity)
  const variantAssetKeys = referenceVariants
    .map((variant) => readText(variant.assetKey))
    .filter(Boolean)
  const keys = [
    selectedReferenceVariantAssetKey,
    readText(metadata.referenceSheetAssetKey),
    ...readStringArray(metadata.referenceSheetAssetKeys),
    ...variantAssetKeys,
    readText(metadata.referenceSheetUrl),
    readText(metadata.referenceSheetImageUrl),
    readText(metadata.referenceSheetStoragePath),
    readText(metadata.imageUrl),
    readText(metadata.image_url),
    readText(metadata.sourceUrl),
    readText(metadata.sourceAssetUrl),
    readText(entity.imageUrl),
    readText(entity.image_url),
    readText(entity.sourceUrl),
    readText(entity.source_url),
    readText(entity.thumbnailAssetKey),
    readText(entity.thumbnail_asset_key),
    readText(metadata.brandAtlasAssetKey),
    readText(metadata.assetKey),
    readText(metadata.storagePath),
  ].filter(Boolean)
  const matching = assets
    .filter((asset) => keys.includes(readText(asset.key)))
    .map((asset) => readText(asset.key))
  return sortReferenceValuesWithPrimary([...keys, ...matching], selectedReferenceVariantAssetKey)
}

const referenceVariantStopWords = new Set([
  'about',
  'after',
  'again',
  'asset',
  'character',
  'default',
  'entity',
  'from',
  'generate',
  'guidance',
  'image',
  'inside',
  'into',
  'look',
  'make',
  'reference',
  'sheet',
  'shot',
  'that',
  'their',
  'them',
  'this',
  'variant',
  'visual',
  'with',
])

const referenceVariantCueWords = new Set([
  'armor',
  'armour',
  'blue',
  'cafe',
  'cape',
  'chamber',
  'costume',
  'dress',
  'gear',
  'gold',
  'green',
  'hall',
  'hat',
  'inside',
  'interior',
  'market',
  'military',
  'outfit',
  'pact',
  'red',
  'robe',
  'room',
  'samurai',
  'silver',
  'suit',
  'temple',
  'uniform',
  'wearing',
  'wears',
  'within',
])

function normalizeReferenceVariantText(value: string) {
  return value.toLowerCase().replace(/[_-]+/g, ' ').replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim()
}

function referenceVariantAssetKey(variant: Record<string, unknown>) {
  return readText(variant.assetKey) || readText(variant.asset_key)
}

function referenceVariantStatus(variant: Record<string, unknown>) {
  return readText(variant.status).toLowerCase()
}

function referenceVariantHasUsableAsset(variant: Record<string, unknown>) {
  if (!referenceVariantAssetKey(variant)) return false
  const status = referenceVariantStatus(variant)
  return !['failed', 'cancelled', 'deleted', 'queued', 'pending', 'running'].includes(status)
}

function referenceVariantCandidatePhrases(variant: Record<string, unknown>) {
  return [
    readText(variant.variantKey),
    readText(variant.variant_key),
    readText(variant.label),
    readText(variant.summary),
    readText(variant.guidance),
    readText(variant.variantType),
    readText(variant.variant_type),
  ]
    .map(normalizeReferenceVariantText)
    .filter((value) => value.length >= 3)
}

function referenceVariantWords(variant: Record<string, unknown>) {
  return [...new Set(referenceVariantCandidatePhrases(variant)
    .flatMap((phrase) => phrase.split(' '))
    .filter((word) => word.length >= 3 && !referenceVariantStopWords.has(word)))]
}

function referenceVariantMatchScore(variant: Record<string, unknown>, prompt: string) {
  const haystack = normalizeReferenceVariantText(prompt)
  if (!haystack) return 0
  let score = 0
  for (const phrase of referenceVariantCandidatePhrases(variant)) {
    if (phrase.length >= 4 && haystack.includes(phrase)) score += phrase.split(' ').length > 1 ? 80 : 40
  }
  for (const word of referenceVariantWords(variant)) {
    if (haystack.split(' ').includes(word) || haystack.includes(word)) score += word.length <= 3 ? 8 : 12
  }
  return score
}

function referenceVariantMatchesPrompt(variant: Record<string, unknown>, prompt: string) {
  return referenceVariantMatchScore(variant, prompt) > 0
}

function promptHasReferenceVariantCue(prompt: string) {
  const words = normalizeReferenceVariantText(prompt).split(' ').filter(Boolean)
  return words.some((word) => referenceVariantCueWords.has(word))
}

function selectReferenceVariantForPromptDetailed(variants: Record<string, unknown>[], prompt: string, entityKey = '') {
  const scored = variants
    .map((variant) => ({
      variant,
      score: referenceVariantMatchScore(variant, prompt),
    }))
    .filter((entry) => entry.score > 0)
    .sort((left, right) => {
      if (right.score !== left.score) return right.score - left.score
      return readText(left.variant.label).localeCompare(readText(right.variant.label))
    })

  const diagnostics: string[] = []
  const completed = scored.find((entry) => referenceVariantHasUsableAsset(entry.variant))
  if (completed) {
    return {
      selectedVariant: completed.variant,
      reason: 'variant_match',
      diagnostics,
    }
  }

  const matchedUnavailable = scored[0]?.variant
  if (matchedUnavailable) {
    const key = readText(matchedUnavailable.variantKey) || readText(matchedUnavailable.variant_key)
    const status = referenceVariantStatus(matchedUnavailable)
    diagnostics.push(`${status === 'queued' || status === 'running' || status === 'pending' ? 'variant_pending' : 'variant_unavailable'}:${entityKey}:${key || 'unknown'}`)
  } else if (variants.length > 0 && promptHasReferenceVariantCue(prompt)) {
    diagnostics.push(`variant_not_found:${entityKey}`)
  }

  return {
    selectedVariant: null,
    reason: 'default',
    diagnostics,
  }
}

function selectReferenceVariantForPrompt(variants: Record<string, unknown>[], prompt: string) {
  return selectReferenceVariantForPromptDetailed(variants, prompt).selectedVariant
}

function defaultReferenceAssetKeyForEntity(entity: Record<string, unknown>, assets: Record<string, unknown>[]) {
  const metadata = asRecord(entity.metadata)
  const keys = [
    readText(metadata.referenceSheetAssetKey),
    ...readStringArray(metadata.referenceSheetAssetKeys),
    readText(metadata.referenceSheetUrl),
    readText(metadata.referenceSheetImageUrl),
    readText(metadata.referenceSheetStoragePath),
    readText(metadata.imageUrl),
    readText(metadata.image_url),
    readText(metadata.sourceUrl),
    readText(metadata.sourceAssetUrl),
    readText(entity.imageUrl),
    readText(entity.image_url),
    readText(entity.sourceUrl),
    readText(entity.source_url),
    readText(entity.thumbnailAssetKey),
    readText(entity.thumbnail_asset_key),
    readText(metadata.assetKey),
    readText(metadata.storagePath),
  ].filter(Boolean)
  const matching = assets
    .filter((asset) => keys.includes(readText(asset.key)))
    .map((asset) => readText(asset.key))
  return sortReferenceValues([...keys, ...matching])[0] ?? ''
}

function resolveImageOutputReferenceSelection(entity: Record<string, unknown>, assets: Record<string, unknown>[], prompt: string) {
  const metadata = asRecord(entity.metadata)
  const entityKey = readText(entity.key)
  const referenceVariants = Array.isArray(metadata.referenceVariants)
    ? metadata.referenceVariants.map(asRecord)
    : Array.isArray(entity.referenceVariants)
      ? entity.referenceVariants.map(asRecord)
      : []
  const selected = selectReferenceVariantForPromptDetailed(referenceVariants, prompt, entityKey)
  const selectedVariant = selected.selectedVariant
  const selectedVariantAssetKey = selectedVariant ? referenceVariantAssetKey(selectedVariant) : ''
  const defaultAssetKey = defaultReferenceAssetKeyForEntity(entity, assets)
  const primaryAssetKey = selectedVariantAssetKey || defaultAssetKey
  const selectedReferenceVariantKey = selectedVariant
    ? readText(selectedVariant.variantKey) || readText(selectedVariant.variant_key)
    : 'default'
  return {
    primaryAssetKey,
    selectedReferenceVariantKey,
    selectedReferenceVariantAssetKey: selectedVariantAssetKey,
    selectedReferenceVariantLabel: selectedVariant ? readText(selectedVariant.label) || selectedReferenceVariantKey : 'Default',
    selectedReferenceVariantSummary: selectedVariant ? readText(selectedVariant.summary) : '',
    selectedReferenceVariantType: selectedVariant ? readText(selectedVariant.variantType) || readText(selectedVariant.variant_type) : 'default',
    referenceSelectionReason: selected.reason,
    referenceDiagnostics: primaryAssetKey ? selected.diagnostics : [...selected.diagnostics, `missing_reference:${entityKey}`],
    referenceVariants,
  }
}

function buildDeterministicComicAssetPack(context: Record<string, unknown>) {
  const entities = Array.isArray(context.entities) ? context.entities.map(asRecord) : []
  const assets = Array.isArray(context.assets) ? context.assets.map(asRecord) : []
  const packedEntities = entities.slice(0, 16).map((entity) => {
    const metadata = asRecord(entity.metadata)
    const referenceVariants = Array.isArray(metadata.referenceVariants)
      ? metadata.referenceVariants.map(asRecord)
      : Array.isArray(entity.referenceVariants)
        ? entity.referenceVariants.map(asRecord)
        : []
    const selectedReferenceVariantKey = readText(metadata.selectedReferenceVariantKey) || readText(entity.selectedReferenceVariantKey) || 'default'
    const selectedVariant = selectedReferenceVariantKey && selectedReferenceVariantKey !== 'default'
      ? referenceVariants.find((variant) => {
        const key = readText(variant.variantKey) || readText(variant.variant_key)
        return key === selectedReferenceVariantKey
      }) ?? null
      : null
    const selectedReferenceVariantAssetKey = selectedVariant
      ? referenceVariantAssetKey(selectedVariant) || selectedReferenceVariantAssetKeyForEntity(entity)
      : ''
    const assetKeys = entityAssetKeys(entity, assets)
    const primaryAssetKey = selectedReferenceVariantAssetKey || assetKeys[0] || ''
    return {
      key: readText(entity.key),
      name: readText(entity.name),
      type: readText(entity.nodeType ?? entity.node_type),
      role: readText(entity.nodeType ?? entity.node_type),
      summary: readText(entity.summary),
      visualDescription: readOutputEntityVisualDescription(entity),
      visualTraits: readOutputEntityVisualTraits(entity),
      visualTraitMap: readOutputEntityVisualTraitMap(entity),
      voice: readOutputEntityVoiceIdentity(entity),
      voiceDescription: readOutputEntityVoiceDescription(entity),
      referenceVariants,
      selectedReferenceVariantKey,
      selectedReferenceVariantLabel: selectedVariant ? readText(selectedVariant.label) || selectedReferenceVariantKey : 'Default',
      selectedReferenceVariantSummary: selectedVariant ? readText(selectedVariant.summary) : '',
      selectedReferenceVariantType: selectedVariant ? readText(selectedVariant.variantType) || readText(selectedVariant.variant_type) : 'default',
      selectedReferenceVariantAssetKey,
      primaryAssetKey,
      assetKeys: sortReferenceValuesWithPrimary(assetKeys, primaryAssetKey),
    }
  }).filter((entity) => entity.key || entity.name)
  return {
    entities: packedEntities,
    selectedReferenceVariants: packedEntities
      .filter((entity) => readText(entity.selectedReferenceVariantKey) && readText(entity.selectedReferenceVariantKey) !== 'default')
      .map((entity) => ({
        entityKey: entity.key,
        entityName: entity.name,
        variantKey: entity.selectedReferenceVariantKey,
        label: entity.selectedReferenceVariantLabel,
        summary: entity.selectedReferenceVariantSummary,
        variantType: entity.selectedReferenceVariantType,
        assetKey: entity.selectedReferenceVariantAssetKey,
      })),
    missingReferenceEntityKeys: packedEntities.filter((entity) => entity.assetKeys.length === 0).map((entity) => entity.key),
  }
}

async function refreshWorldContextVisualReferences(client: DatabaseClient, run: OutputWorkflowRun, context: Record<string, unknown>) {
  const entities = Array.isArray(context.entities) ? context.entities.map(asRecord) : []
  if (entities.length === 0) return context
  const entityKeys = [...new Set(entities.map((entity) => readText(entity.key)).filter(Boolean))]
  if (entityKeys.length === 0) return context

  const latestResponse = await client
    .from('world_entities')
    .select('key, thumbnail_asset_key, metadata, updated_at')
    .eq('draft_id', run.draftId)
    .in('key', entityKeys)
  const latestRows = latestResponse.error ? [] : (latestResponse.data ?? []).map(asRecord)
  const latestByKey = new Map(latestRows.map((row) => [readText(row.key), row]).filter(([key]) => key))
  const variantResponse = await client
    .from('world_entity_visual_variants')
    .select('entity_key, variant_key, label, summary, variant_type, asset_key, guidance, status, metadata')
    .eq('draft_id', run.draftId)
    .in('entity_key', entityKeys)
  const variantsByEntityKey = new Map<string, Record<string, unknown>[]>()
  if (!variantResponse.error) {
    for (const row of variantResponse.data ?? []) {
      const record = asRecord(row)
      const entityKey = readText(record.entity_key)
      if (!entityKey) continue
      const entry = {
        variantKey: readText(record.variant_key),
        label: readText(record.label),
        summary: readText(record.summary),
        variantType: readText(record.variant_type),
        assetKey: readText(record.asset_key),
        guidance: readText(record.guidance),
        status: readText(record.status),
        metadata: asRecord(record.metadata),
      }
      variantsByEntityKey.set(entityKey, [...(variantsByEntityKey.get(entityKey) ?? []), entry])
    }
  }
  const refreshedEntities = entities.map((entity) => {
    const key = readText(entity.key)
    const latest = latestByKey.get(key)
    const variants = variantsByEntityKey.get(key) ?? []
    const selectedVariant = selectReferenceVariantForPrompt(variants, run.prompt)
    if (!latest && variants.length === 0) return entity
    const entityMetadata = asRecord(entity.metadata)
    const latestMetadata = asRecord(latest?.metadata)
    const latestThumbnail = readText(latest?.thumbnail_asset_key)
    return {
      ...entity,
      thumbnailAssetKey: latestThumbnail || readText(entity.thumbnailAssetKey),
      thumbnail_asset_key: latestThumbnail || readText(entity.thumbnail_asset_key),
      metadata: {
        ...entityMetadata,
        ...latestMetadata,
        referenceVariants: variants,
        selectedReferenceVariantKey: selectedVariant ? readText(selectedVariant.variantKey) : 'default',
        selectedReferenceVariantAssetKey: selectedVariant ? readText(selectedVariant.assetKey) : '',
      },
      referenceVariants: variants,
      selectedReferenceVariantKey: selectedVariant ? readText(selectedVariant.variantKey) : 'default',
      selectedReferenceVariantAssetKey: selectedVariant ? readText(selectedVariant.assetKey) : '',
      updatedAt: readText(latest?.updated_at) || readText(entity.updatedAt),
      updated_at: readText(latest?.updated_at) || readText(entity.updated_at),
    }
  })

  const existingAssets = Array.isArray(context.assets) ? context.assets.map(asRecord) : []
  const existingAssetKeys = new Set(existingAssets.map((asset) => readText(asset.key)).filter(Boolean))
  const referencedAssetKeys = refreshedEntities
    .flatMap((entity) => entityAssetKeys(entity, existingAssets))
    .filter((value) => value && !isDirectReferenceUrl(value) && !isProjectAssetStoragePath(value) && !existingAssetKeys.has(value))
  const missingAssetKeys = [...new Set(referencedAssetKeys)]
  let hydratedAssets: Record<string, unknown>[] = []
  if (missingAssetKeys.length > 0) {
    const assetResponse = await client
      .from('project_assets')
      .select('key, name, kind, mime_type, storage_path, metadata')
      .eq('project_id', run.projectId)
      .in('key', missingAssetKeys)
    hydratedAssets = assetResponse.error
      ? []
      : (assetResponse.data ?? []).map((asset) => ({
        key: readText(asRecord(asset).key),
        name: readText(asRecord(asset).name),
        kind: readText(asRecord(asset).kind),
        mimeType: readText(asRecord(asset).mime_type),
        mime_type: readText(asRecord(asset).mime_type),
        storagePath: readText(asRecord(asset).storage_path),
        storage_path: readText(asRecord(asset).storage_path),
        metadata: asRecord(asRecord(asset).metadata),
      }))
  }

  return {
    ...context,
    entities: refreshedEntities,
    assets: [...existingAssets, ...hydratedAssets],
    refreshedVisualReferences: true,
    refreshedVisualReferenceAssetKeys: hydratedAssets.map((asset) => readText(asset.key)).filter(Boolean),
  }
}

function buildDeterministicImageAssetPack(context: Record<string, unknown>, options: number | { limit?: number; prompt?: string } = 8) {
  const limit = typeof options === 'number' ? options : Math.max(1, Math.floor(Number(options.limit ?? 8) || 8))
  const prompt = typeof options === 'number' ? '' : readText(options.prompt)
  const entities = Array.isArray(context.entities) ? context.entities.map(asRecord) : []
  const assets = Array.isArray(context.assets) ? context.assets.map(asRecord) : []
  const packedEntities = entities.slice(0, limit).map((entity) => {
    const visualDescription = readOutputEntityVisualDescription(entity)
    const referenceSelection = resolveImageOutputReferenceSelection(entity, assets, prompt)
    return {
      key: readText(entity.key),
      name: readText(entity.name),
      type: readText(entity.nodeType ?? entity.node_type),
      role: readText(entity.nodeType ?? entity.node_type),
      summary: readText(entity.summary),
      visualDescription,
      visualTraits: readOutputEntityVisualTraits(entity),
      visualTraitMap: readOutputEntityVisualTraitMap(entity),
      referenceVariants: referenceSelection.referenceVariants,
      selectedReferenceVariantKey: referenceSelection.selectedReferenceVariantKey,
      selectedReferenceVariantLabel: referenceSelection.selectedReferenceVariantLabel,
      selectedReferenceVariantSummary: referenceSelection.selectedReferenceVariantSummary,
      selectedReferenceVariantType: referenceSelection.selectedReferenceVariantType,
      selectedReferenceVariantAssetKey: referenceSelection.selectedReferenceVariantAssetKey,
      referenceSelectionReason: referenceSelection.referenceSelectionReason,
      referenceDiagnostics: referenceSelection.referenceDiagnostics,
      primaryAssetKey: referenceSelection.primaryAssetKey,
      assetKeys: referenceSelection.primaryAssetKey ? [referenceSelection.primaryAssetKey] : [],
    }
  }).filter((entity) => entity.key || entity.name)
  const referenceDiagnostics = [...new Set(packedEntities.flatMap((entity) => readStringArray(entity.referenceDiagnostics)))]
  return {
    entities: packedEntities,
    selectedReferenceVariants: packedEntities
      .filter((entity) => readText(entity.selectedReferenceVariantKey) && readText(entity.selectedReferenceVariantKey) !== 'default')
      .map((entity) => ({
        entityKey: entity.key,
        entityName: entity.name,
        variantKey: entity.selectedReferenceVariantKey,
        label: entity.selectedReferenceVariantLabel,
        summary: entity.selectedReferenceVariantSummary,
        variantType: entity.selectedReferenceVariantType,
        assetKey: entity.selectedReferenceVariantAssetKey,
      })),
    referenceDiagnostics,
    missingReferenceEntityKeys: packedEntities.filter((entity) => entity.assetKeys.length === 0).map((entity) => entity.key),
  }
}

function buildOutputReferenceSelectionSnapshot(outputs: unknown) {
  const record = asRecord(outputs)
  const assetPackCandidate = asRecord(record.assetPack)
  const assetPack = Object.keys(assetPackCandidate).length > 0 ? assetPackCandidate : asRecord(record.asset_pack)
  const entities = Array.isArray(assetPack.entities) ? assetPack.entities.map(asRecord) : []
  if (entities.length === 0) return null
  const selectedReferenceVariants = entities
    .filter((entity) => {
      const selectedKey = readText(entity.selectedReferenceVariantKey)
      return selectedKey && selectedKey !== 'default'
    })
    .map((entity) => ({
      entityKey: readText(entity.key),
      entityName: readText(entity.name),
      variantKey: readText(entity.selectedReferenceVariantKey),
      label: readText(entity.selectedReferenceVariantLabel) || readText(entity.selectedReferenceVariantKey),
      summary: readText(entity.selectedReferenceVariantSummary),
      variantType: readText(entity.selectedReferenceVariantType),
      assetKey: readText(entity.selectedReferenceVariantAssetKey) || readText(entity.primaryAssetKey) || readStringArray(entity.assetKeys)[0] || '',
    }))
    .filter((entry) => entry.entityKey && entry.variantKey)
  return {
    source: 'workflow_reference_selection',
    updatedAt: new Date().toISOString(),
    selectedEntityKeys: entities.map((entity) => readText(entity.key)).filter(Boolean),
    selectedReferenceVariants,
    entities: entities.map((entity) => ({
      key: readText(entity.key),
      name: readText(entity.name),
      type: readText(entity.type) || readText(entity.role),
      summary: readText(entity.summary),
      primaryAssetKey: readText(entity.primaryAssetKey) || readStringArray(entity.assetKeys)[0] || '',
      assetKeys: readStringArray(entity.assetKeys).slice(0, 4),
      selectedReferenceVariantKey: readText(entity.selectedReferenceVariantKey) || 'default',
      selectedReferenceVariantLabel: readText(entity.selectedReferenceVariantLabel) || (readText(entity.selectedReferenceVariantKey) === 'default' ? 'Default' : readText(entity.selectedReferenceVariantKey)),
      selectedReferenceVariantSummary: readText(entity.selectedReferenceVariantSummary),
      selectedReferenceVariantType: readText(entity.selectedReferenceVariantType),
      selectedReferenceVariantAssetKey: readText(entity.selectedReferenceVariantAssetKey),
    })),
  }
}

async function persistOutputRequestReferenceSelection(client: DatabaseClient, run: OutputWorkflowRun, outputs: unknown) {
  const snapshot = buildOutputReferenceSelectionSnapshot(outputs)
  if (!snapshot) return
  const requestResponse = await client
    .from('output_requests')
    .select('id, metadata')
    .eq('draft_id', run.draftId)
    .eq('workflow_id', run.workflowId)
    .order('created_at', { ascending: false })
    .limit(1)
    .maybeSingle()
  if (requestResponse.error || !requestResponse.data) return
  const requestRow = asRecord(requestResponse.data)
  const requestId = readText(requestRow.id)
  if (!requestId) return
  const metadata = asRecord(requestRow.metadata)
  const updateResponse = await client
    .from('output_requests')
    .update({
      metadata: {
        ...metadata,
        outputReferenceSelection: snapshot,
      },
    })
    .eq('id', requestId)
  if (updateResponse.error) throw new Error(updateResponse.error.message)
  await client.rpc('refresh_output_request_status_projection', { p_request_id: requestId })
}

async function persistSequenceAnimaticContinuityRequestState(input: {
  client: DatabaseClient
  run: OutputWorkflowRun
  workflow: OutputWorkflow
  artifactKey: string
  continuityPack: Record<string, unknown>
  blockStates: Record<string, unknown>
  pendingDeltas: Record<string, unknown>
}) {
  const requestResponse = await input.client
    .from('output_requests')
    .select('id, metadata')
    .eq('draft_id', input.run.draftId)
    .eq('workflow_id', input.workflow.id)
    .order('created_at', { ascending: false })
    .limit(1)
    .maybeSingle()
  if (requestResponse.error) throw new Error(requestResponse.error.message)
  if (!requestResponse.data) return

  const requestRow = asRecord(requestResponse.data)
  const requestId = readText(requestRow.id)
  if (!requestId) return

  const metadata = asRecord(requestRow.metadata)
  const mergedBlockStates = {
    ...asRecord(metadata.blockStates),
    ...input.blockStates,
  }
  const continuityGraphStatus = readText(input.continuityPack.continuityGraphStatus ?? input.continuityPack.continuity_graph_status)
  const assetGenerationStatus = readText(input.continuityPack.assetGenerationStatus ?? input.continuityPack.asset_generation_status)
  const globalStructureState = asRecord(input.continuityPack.globalStructureState ?? input.continuityPack.global_structure_state)
  const coverage = asRecord(input.continuityPack.coverage)
  const updateResponse = await input.client
    .from('output_requests')
    .update({
      metadata: {
        ...metadata,
        screenplayAnimaticRole: readText(metadata.screenplayAnimaticRole) || 'continuity_pack',
        sequenceAnimaticRole: readText(metadata.sequenceAnimaticRole) || 'continuity_pack',
        blockStates: mergedBlockStates,
        pendingDeltas: input.pendingDeltas,
        globalStructureState: Object.keys(globalStructureState).length > 0 ? globalStructureState : asRecord(metadata.globalStructureState),
        continuityCoverage: Object.keys(coverage).length > 0 ? coverage : asRecord(metadata.continuityCoverage),
        continuityGraphStatus: continuityGraphStatus || sequenceAnimaticContinuityGraphStatusFromBlockStates(mergedBlockStates),
        continuityPackHash: readText(input.continuityPack.continuityPackHash),
        assetGenerationStatus: assetGenerationStatus || readText(metadata.assetGenerationStatus) || 'none',
        lastContinuityStructureArtifactKey: input.artifactKey,
        continuityStructureUpdatedAt: new Date().toISOString(),
      },
    })
    .eq('id', requestId)
  if (updateResponse.error) throw new Error(updateResponse.error.message)
  await input.client.rpc('refresh_output_request_status_projection', { p_request_id: requestId })
}

async function persistSequenceAnimaticDirectorPlanRequestState(input: {
  client: DatabaseClient
  run: OutputWorkflowRun
  workflow: OutputWorkflow
  artifactKey: string
  directorPlan: Record<string, unknown>
}) {
  const requestResponse = await input.client
    .from('output_requests')
    .select('id, project_id, draft_id, metadata')
    .eq('draft_id', input.run.draftId)
    .eq('workflow_id', input.workflow.id)
    .order('created_at', { ascending: false })
    .limit(1)
    .maybeSingle()
  if (requestResponse.error) throw new Error(requestResponse.error.message)
  if (!requestResponse.data) return

  const requestRow = asRecord(requestResponse.data)
  const requestId = readText(requestRow.id)
  if (!requestId) return

  const metadata = asRecord(requestRow.metadata)
  const updateResponse = await input.client
    .from('output_requests')
    .update({
      metadata: {
        ...metadata,
        screenplayAnimaticRole: readText(metadata.screenplayAnimaticRole) || 'master',
        sequenceAnimaticRole: readText(metadata.sequenceAnimaticRole) || 'master',
        graphSpecVersion: 'sequence_animatic_graph_v2',
        directorPlanStatus: 'ready',
        shotContinuityPlanStatus: 'ready',
        directorPlanHash: readText(input.directorPlan.shotPlanHash) || hashOutputWorkflowValue(input.directorPlan),
        shotContinuityPlanHash: readText(input.directorPlan.shotPlanHash) || hashOutputWorkflowValue(input.directorPlan),
        directorPlanArtifactKey: input.artifactKey,
        shotContinuityPlanArtifactKey: input.artifactKey,
        directorPlanUpdatedAt: new Date().toISOString(),
        shotContinuityPlanUpdatedAt: new Date().toISOString(),
      },
    })
    .eq('id', requestId)
  if (updateResponse.error) throw new Error(updateResponse.error.message)

  const events: Record<string, unknown>[] = []
  let sequence = 1
  events.push({
    project_id: input.run.projectId,
    draft_id: input.run.draftId,
    request_id: requestId,
    workflow_id: input.workflow.id,
    run_id: input.run.id,
    sequence: sequence++,
      event_type: 'director_plan_ready',
      payload: {
        shotCount: readArray(input.directorPlan.shots).length,
        blockCount: readArray(input.directorPlan.blocks).length,
        assetRequirementCount: readArray(input.directorPlan.assetRequirements).length,
        shotPlanHash: readText(input.directorPlan.shotPlanHash),
        shotContinuityPlanHash: readText(input.directorPlan.shotPlanHash),
      },
    metadata: { source: 'sequence_animatic_director_plan' },
  })
  for (const block of readArray(input.directorPlan.blocks).map(asRecord)) {
    events.push({
      project_id: input.run.projectId,
      draft_id: input.run.draftId,
      request_id: requestId,
      workflow_id: input.workflow.id,
      run_id: input.run.id,
      sequence: sequence++,
      event_type: 'block_planned',
      payload: {
        blockId: readText(block.id),
        index: Number(block.index ?? 0) || null,
        title: readText(block.title),
        summary: readText(block.summary),
        shotIds: readStringArray(block.shotIds),
        status: readText(block.status) || 'planned',
      },
      metadata: { source: 'sequence_animatic_director_plan' },
    })
  }
  for (const shot of readArray(input.directorPlan.shots).map(asRecord)) {
    const shotId = readText(shot.id)
    events.push({
      project_id: input.run.projectId,
      draft_id: input.run.draftId,
      request_id: requestId,
      workflow_id: input.workflow.id,
      run_id: input.run.id,
      sequence: sequence++,
      event_type: 'shot_registered',
      payload: {
        shotId,
        index: Number(shot.index ?? 0) || null,
        storyboardBlockId: readText(shot.storyboardBlockId),
        title: readText(shot.title),
        action: compactSequenceAnimaticText(shot.action ?? shot.description, 600),
        visibleCharacterRefIds: readStringArray(shot.visibleCharacterRefIds ?? shot.visible_character_ref_ids),
        speakerRefIds: readStringArray(shot.speakerRefIds ?? shot.speaker_ref_ids),
        propRefIds: readStringArray(shot.propRefIds ?? shot.prop_ref_ids),
        locationRefIds: readStringArray(shot.locationRefIds ?? shot.location_ref_ids),
        sceneGraphBinding: asRecord(shot.sceneGraphBinding ?? shot.scene_graph_binding),
        assetRequirements: readArray(shot.assetRequirements ?? shot.asset_requirements).map(asRecord),
      },
      metadata: { source: 'sequence_animatic_director_plan' },
    })
  }
  const graph = asRecord(input.directorPlan.continuityGraphV2 ?? input.directorPlan.continuity_graph_v2)
  const graphNodes = [
    ...readArray(graph.locationSets).map(asRecord).map((entry) => ({ ...entry, graphNodeKind: 'location_set' })),
    ...readArray(graph.zones).map(asRecord).map((entry) => ({ ...entry, graphNodeKind: 'zone' })),
    ...readArray(graph.spots).map(asRecord).map((entry) => ({ ...entry, graphNodeKind: 'spot' })),
    ...readArray(graph.angles).map(asRecord).map((entry) => ({ ...entry, graphNodeKind: 'angle' })),
    ...readArray(graph.assetAnchors).map(asRecord).map((entry) => ({ ...entry, graphNodeKind: readText(entry.type) || 'asset_anchor' })),
  ]
  for (const node of graphNodes.slice(0, 200)) {
    events.push({
      project_id: input.run.projectId,
      draft_id: input.run.draftId,
      request_id: requestId,
      workflow_id: input.workflow.id,
      run_id: input.run.id,
      sequence: sequence++,
      event_type: 'scene_graph_node_registered',
      payload: {
        nodeId: readText(node.id),
        nodeKind: readText(node.graphNodeKind),
        name: readText(node.name),
        visualBrief: readText(node.visualBrief),
        shotIds: readStringArray(node.shotIds),
        storyboardBlockIds: readStringArray(node.storyboardBlockIds),
      },
      metadata: { source: 'sequence_animatic_director_plan' },
    })
  }
  const eventTypes = ['director_plan_ready', 'block_planned', 'shot_registered', 'scene_graph_node_registered']
  const deleteEvents = await input.client
    .from('output_request_events')
    .delete()
    .eq('request_id', requestId)
    .in('event_type', eventTypes)
  if (deleteEvents.error) throw new Error(deleteEvents.error.message)
  if (events.length > 0) {
    const sequenceResponse = await input.client
      .from('output_request_events')
      .select('sequence')
      .eq('request_id', requestId)
      .order('sequence', { ascending: false })
      .limit(1)
      .maybeSingle()
    if (sequenceResponse.error) throw new Error(sequenceResponse.error.message)
    const sequenceOffset = Number(asRecord(sequenceResponse.data).sequence ?? 0) || 0
    const sequencedEvents = events.map((event, index) => ({
      ...event,
      sequence: sequenceOffset + index + 1,
    }))
    const insertEvents = await input.client
      .from('output_request_events')
      .insert(sequencedEvents)
    if (insertEvents.error) throw new Error(insertEvents.error.message)
  }
  await input.client.rpc('refresh_output_request_status_projection', { p_request_id: requestId })
}

async function insertSequenceAnimaticEvent(input: {
  client: DatabaseClient
  projectId: string
  draftId: string
  requestId: string
  workflowId?: string | null
  runId?: string | null
  eventType: string
  payload?: Record<string, unknown>
  metadata?: Record<string, unknown>
  dedupe?: Record<string, string>
}) {
  if (!input.requestId || !input.eventType) return
  if (input.dedupe && Object.keys(input.dedupe).length > 0) {
    let query = input.client
      .from('output_request_events')
      .delete()
      .eq('request_id', input.requestId)
      .eq('event_type', input.eventType)
    for (const [key, value] of Object.entries(input.dedupe)) {
      if (!value) continue
      query = query.eq(`payload->>${key}`, value)
    }
    const deleteResponse = await query
    if (deleteResponse.error) throw new Error(deleteResponse.error.message)
  }
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const latestResponse = await input.client
      .from('output_request_events')
      .select('sequence')
      .eq('request_id', input.requestId)
      .order('sequence', { ascending: false })
      .limit(1)
      .maybeSingle()
    if (latestResponse.error) throw new Error(latestResponse.error.message)
    const sequence = (Number(asRecord(latestResponse.data).sequence ?? 0) || 0) + 1
    const insertResponse = await input.client
      .from('output_request_events')
      .insert({
        project_id: input.projectId,
        draft_id: input.draftId,
        request_id: input.requestId,
        workflow_id: input.workflowId ?? null,
        run_id: input.runId ?? null,
        sequence,
        event_type: input.eventType,
        payload: input.payload ?? {},
        metadata: input.metadata ?? {},
      })
    if (!insertResponse.error) return
    if (!String(insertResponse.error.message ?? '').includes('output_request_events_request_id_sequence_key') && !String(insertResponse.error.message ?? '').includes('duplicate key')) {
      throw new Error(insertResponse.error.message)
    }
  }
}

async function clearSequenceAnimaticShotContinuityStreamEvents(input: {
  client: DatabaseClient
  requestId: string
  nodeKey?: string
}) {
  if (!input.requestId) return
  let query = input.client
    .from('output_request_events')
    .delete()
    .eq('request_id', input.requestId)
    .in('event_type', [
      'shot_continuity_stream_started',
      'shot_continuity_stream_warning',
      'shot_streamed',
      'local_reference_registered',
      'coverage_setup_registered',
      'shot_continuity_stream_done',
      'shot_continuity_stream_failed',
      'block_planned',
      'scene_graph_node_registered',
      'scene_graph_relation_registered',
    ])
  if (input.nodeKey) {
    query = query.eq('metadata->>nodeKey', input.nodeKey)
  }
  const response = await query
  if (response.error) throw new Error(response.error.message)
}

async function runSequenceAnimaticShotContinuityPlanStream(input: {
  client: DatabaseClient
  run: OutputWorkflowRun
  workflow: OutputWorkflow
  node: OutputWorkflowNode
  requestId: string
  prompt: string
  instructions: string
  maxOutputTokens: number
  taskClass?: 'continuity_structure' | 'scene_shot_plan'
  reasoningEffortOverride?: 'minimal' | 'low' | 'medium' | 'high' | null
  shouldCancel?: () => Promise<boolean>
  onProgress?: (progress: {
    providerRequestId: string
    providerStatus: string
    providerMode: string
    lastProviderPollAt: string
    providerStartedAt: string
  }) => Promise<void>
}) {
  const model = outputWorkflowTextModel()
  const providerStartedAt = new Date().toISOString()
  const accumulator = createSequenceAnimaticShotContinuityStreamAccumulator()
  let streamRecordBuffer = ''
  let providerRequestId = ''
  let acceptedRecordCount = 0
  let warningCount = 0
  let lastProgressAt = 0

  const progress = async (providerStatus: string, force = false) => {
    const now = Date.now()
    if (!force && now - lastProgressAt < 15_000) return
    lastProgressAt = now
    await input.onProgress?.({
      providerRequestId,
      providerStatus,
      providerMode: 'stream',
      lastProviderPollAt: new Date().toISOString(),
      providerStartedAt,
    })
  }

  const emitEvent = async (
    eventType: string,
    payload: Record<string, unknown> = {},
    dedupe?: Record<string, string>,
  ) => {
    await insertSequenceAnimaticEvent({
      client: input.client,
      projectId: input.run.projectId,
      draftId: input.run.draftId,
      requestId: input.requestId,
      workflowId: input.workflow.id,
      runId: input.run.id,
      eventType,
      payload,
      metadata: {
        source: 'sequence_animatic_shot_continuity_stream',
        nodeKey: input.node.key,
        providerRequestId: providerRequestId || null,
      },
      dedupe,
    })
  }

  const processRecordText = async (recordText: string) => {
    const parsed = parseSequenceAnimaticStreamRecord(recordText)
    if (!parsed.record) {
      warningCount += 1
      await emitEvent('shot_continuity_stream_warning', {
        warning: parsed.error instanceof z.ZodError
          ? compactSchemaDiagnostics(parsed.error).join('; ')
          : parsed.error instanceof Error
            ? parsed.error.message
            : parsed.error
              ? String(parsed.error)
              : 'Malformed shot continuity stream record.',
        sample: recordText.slice(0, 700),
        warningCount,
      })
      return
    }

    applySequenceAnimaticShotContinuityStreamRecord(accumulator, parsed.record)
    acceptedRecordCount += 1

    if (parsed.record.kind === 'plan_start') {
      await emitEvent('shot_continuity_stream_started', {
        contractVersion: parsed.record.contractVersion,
        graphSpecVersion: parsed.record.graphSpecVersion,
        note: parsed.record.note,
      })
      return
    }
    if (parsed.record.kind === 'block') {
      await emitEvent('block_planned', {
        blockId: parsed.record.id,
        index: parsed.record.index,
        title: parsed.record.title,
        summary: parsed.record.summary,
        shotIds: parsed.record.shotIds,
        status: 'planning',
        streamed: true,
        block: parsed.record,
      }, { blockId: parsed.record.id })
      return
    }
    if (parsed.record.kind === 'shot') {
      await emitEvent('shot_streamed', {
        shotId: parsed.record.id,
        index: parsed.record.index,
        storyboardBlockId: parsed.record.blockId,
        blockId: parsed.record.blockId,
        title: parsed.record.title,
        action: compactSequenceAnimaticText(parsed.record.action, 800),
        status: 'planning',
        shot: parsed.record,
      }, { shotId: parsed.record.id })
      return
    }
    if (parsed.record.kind === 'scene_graph_addition') {
      await emitEvent('scene_graph_node_registered', {
        nodeId: parsed.record.id,
        nodeKind: parsed.record.nodeKind,
        name: parsed.record.name,
        visualBrief: parsed.record.visualBrief,
        shotIds: parsed.record.shotIds,
        storyboardBlockIds: [...new Set([...parsed.record.storyboardBlockIds, ...parsed.record.blockIds])],
        status: 'planning',
        streamed: true,
        node: parsed.record,
      }, { nodeId: parsed.record.id })
      return
    }
    if (parsed.record.kind === 'spot_relation') {
      await emitEvent('scene_graph_relation_registered', {
        sourceId: parsed.record.sourceId,
        targetId: parsed.record.targetId,
        relationship: parsed.record.relationship,
        evidence: parsed.record.evidence,
        direction: parsed.record.direction,
        screenDirection: parsed.record.screenDirection,
        status: 'planning',
        streamed: true,
        relation: parsed.record,
      }, { sourceId: parsed.record.sourceId, targetId: parsed.record.targetId, relationship: parsed.record.relationship })
      return
    }
    if (parsed.record.kind === 'coverage_setup') {
      await emitEvent('coverage_setup_registered', {
        setupId: parsed.record.id,
        sceneId: parsed.record.sceneId || parsed.record.scene_id,
        setupKind: parsed.record.setupKind || parsed.record.setup_kind,
        title: parsed.record.title,
        setId: parsed.record.setId || parsed.record.set_id,
        zoneId: parsed.record.zoneId || parsed.record.zone_id,
        primarySpotId: parsed.record.primarySpotId || parsed.record.primary_spot_id,
        spotIds: sequenceAnimaticUniqueTexts([parsed.record.spotIds, parsed.record.spot_ids]),
        viewpointId: parsed.record.viewpointId || parsed.record.viewpoint_id,
        characterRefIds: sequenceAnimaticUniqueTexts([parsed.record.characterRefIds, parsed.record.character_ref_ids]),
        screenDirection: parsed.record.screenDirection || parsed.record.screen_direction,
        camera: parsed.record.camera,
        lighting: parsed.record.lighting,
        stagingBrief: parsed.record.stagingBrief || parsed.record.staging_brief,
        continuityFromSetupId: parsed.record.continuityFromSetupId || parsed.record.continuity_from_setup_id,
        continuityMode: parsed.record.continuityMode || parsed.record.continuity_mode,
        usedShotIds: sequenceAnimaticUniqueTexts([parsed.record.usedShotIds, parsed.record.used_shot_ids]),
        blockIds: sequenceAnimaticUniqueTexts([parsed.record.blockIds, parsed.record.block_ids]),
        required: parsed.record.required,
        status: 'planning',
        streamed: true,
        coverageSetup: parsed.record,
      }, { setupId: parsed.record.id })
      return
    }
    if (parsed.record.kind === 'local_reference') {
      await emitEvent('local_reference_registered', {
        referenceId: parsed.record.id,
        referenceType: parsed.record.type,
        name: parsed.record.name,
        visualBrief: parsed.record.visualBrief,
        shotIds: parsed.record.usedShotIds,
        blockIds: parsed.record.blockIds,
        required: parsed.record.required,
        importance: parsed.record.importance,
        status: 'planning',
        localReference: parsed.record,
      }, { referenceId: parsed.record.id })
      return
    }
    if (parsed.record.kind === 'plan_done') {
      await emitEvent('shot_continuity_stream_done', {
        shotCount: parsed.record.shotCount,
        blockCount: parsed.record.blockCount,
        orderedShotIds: parsed.record.orderedShotIds,
        orderedBlockIds: parsed.record.orderedBlockIds,
        notes: parsed.record.notes,
        acceptedRecordCount,
        warningCount,
      })
    }
  }

  await clearSequenceAnimaticShotContinuityStreamEvents({
    client: input.client,
    requestId: input.requestId,
    nodeKey: input.node.key,
  })
  await emitEvent('shot_continuity_stream_started', {
    contractVersion: 'shot_continuity_plan_v2',
    graphSpecVersion: 'sequence_animatic_graph_v2',
    status: 'streaming',
  })
  await progress('streaming', true)

  let response: OpenAiResponseResult
  try {
    const continuityPolicy = resolveOutputTextModelPolicy(input.taskClass ?? 'continuity_structure')
    const reasoning = input.reasoningEffortOverride !== undefined
      ? (input.reasoningEffortOverride ? { effort: input.reasoningEffortOverride } : undefined)
      : reasoningPayloadFor(continuityPolicy)
    response = await runOpenAiResponsesStream({
      model: continuityPolicy.model,
      input: input.prompt,
      instructions: input.instructions,
      maxOutputTokens: input.maxOutputTokens,
      reasoning,
      store: false,
      timeoutMs: outputWorkflowChapterTimeoutMs(),
      metadata: {
        graphcore_task: 'sequence_animatic_shot_continuity_jsonl_stream',
        graphcore_node_key: input.node.key,
        graphcore_provider_mode: 'stream',
        outputRequestId: input.requestId,
        workflowRunId: input.run.id,
      },
    }, {
      onEvent: async (event) => {
        const responseRecord = asRecord(event.data.response)
        providerRequestId = readText(responseRecord.id) || readText(event.data.response_id) || readText(event.data.id) || providerRequestId
        await progress(event.type)
        if (await input.shouldCancel?.()) throw new WorkflowCancelledError()
      },
      onTextDelta: async (delta) => {
        streamRecordBuffer += delta
        const extracted = extractCompleteSequenceAnimaticJsonRecords(streamRecordBuffer)
        streamRecordBuffer = extracted.rest
        for (const record of extracted.records) await processRecordText(record)
      },
    })
    providerRequestId = response.id || providerRequestId
    if (streamRecordBuffer.trim().startsWith('{')) {
      await processRecordText(streamRecordBuffer)
      streamRecordBuffer = ''
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Shot continuity stream failed.'
    await emitEvent('shot_continuity_stream_failed', {
      error: message,
      acceptedRecordCount,
      warningCount,
    }).catch(() => null)
    throw error
  }

  if (!response.response.ok) {
    throw new Error(openAiErrorMessage(response, `OpenAI shot continuity stream failed with status ${response.response.status}.`))
  }
  if (response.status !== 'completed') {
    throw new Error(openAiErrorMessage(response, `OpenAI shot continuity stream ended with status ${response.status}.`))
  }

  try {
    const value = finalizeSequenceAnimaticShotContinuityStreamPlan(accumulator)
    await emitEvent('shot_continuity_stream_done', {
      shotCount: value.shots.length,
      blockCount: value.blocks.length,
      orderedShotIds: value.shots.map((shot) => shot.id),
      orderedBlockIds: value.blocks.map((block) => block.id),
      notes: value.notes,
      acceptedRecordCount,
      warningCount,
      status: 'ready',
    })
    await progress('completed', true)
    return {
      value,
      response,
      provider: 'openai',
      model,
      providerRequestId,
      acceptedRecordCount,
      warningCount,
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Shot continuity stream finalization failed.'
    await emitEvent('shot_continuity_stream_failed', {
      error: message,
      acceptedRecordCount,
      warningCount,
    }).catch(() => null)
    throw error
  }
}

async function runSequenceAnimaticShotContinuityPlanStreamWithRetry(
  input: Parameters<typeof runSequenceAnimaticShotContinuityPlanStream>[0],
) {
  const attempts = outputWorkflowShotContinuityStreamAttempts()
  let lastError: unknown = null
  let maxOutputTokens = input.maxOutputTokens
  let reasoningEffortOverride: 'medium' | 'low' | undefined
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      return await runSequenceAnimaticShotContinuityPlanStream({ ...input, maxOutputTokens, reasoningEffortOverride })
    } catch (error) {
      lastError = error
      const truncated = isOpenAiTruncationError(error)
      if ((!truncated && !isRetryableOpenAiStreamError(error)) || attempt >= attempts) throw error
      if (truncated) {
        maxOutputTokens = Math.min(64_000, Math.ceil(maxOutputTokens * 1.6))
        reasoningEffortOverride = reasoningEffortOverride === undefined ? 'medium' : 'low'
      }
      const delayMs = retryDelayMs(attempt)
      await insertSequenceAnimaticEvent({
        client: input.client,
        projectId: input.run.projectId,
        draftId: input.run.draftId,
        requestId: input.requestId,
        workflowId: input.workflow.id,
        runId: input.run.id,
        eventType: 'shot_continuity_stream_warning',
        payload: {
          warning: truncated
            ? `Shot continuity stream was truncated at the output token limit. Retrying attempt ${attempt + 1} of ${attempts} with a larger budget (${maxOutputTokens} tokens, ${reasoningEffortOverride} reasoning).`
            : `Transient shot continuity stream failure. Retrying attempt ${attempt + 1} of ${attempts}.`,
          error: error instanceof Error ? error.message : String(error),
          attempt,
          nextAttempt: attempt + 1,
          maxAttempts: attempts,
          retryDelayMs: delayMs,
          truncated,
          maxOutputTokens,
          reasoningEffortOverride: reasoningEffortOverride ?? null,
          nodeKey: input.node.key,
        },
        metadata: {
          source: 'sequence_animatic_shot_continuity_stream_retry',
          nodeKey: input.node.key,
        },
        dedupe: { nodeKey: input.node.key, attempt: String(attempt) },
      }).catch(() => null)
      await sleep(delayMs)
    }
  }
  throw lastError instanceof Error ? lastError : new Error(String(lastError ?? 'Shot continuity stream failed.'))
}

async function persistSequenceAnimaticNodeProgressEvent(input: {
  client: DatabaseClient
  run: OutputWorkflowRun
  workflow: OutputWorkflow
  node: OutputWorkflowNode
  status: 'running' | 'completed' | 'failed'
  outputs?: Record<string, unknown>
  errorMessage?: string | null
}) {
  const config = asRecord(input.node.config)
  const runMetadata = asRecord(input.run.metadata)
  const role = readText(runMetadata.screenplayAnimaticRole) || readText(runMetadata.sequenceAnimaticRole) || readText(config.screenplayAnimaticRole) || readText(config.sequenceAnimaticRole)
  const masterRequestId = readText(runMetadata.masterRequestId) || readText(config.masterRequestId) || readText(runMetadata.parentRequestId) || readText(config.parentRequestId)
  const outputRequestId = readText(runMetadata.outputRequestId) || readText(config.outputRequestId)
  const purpose = readText(config.purpose)
  if (role === 'master' && input.status === 'completed' && (input.node.key === 'cinematic_v3_screenplay_author' || purpose === 'cinematic_v3_screenplay_author')) {
    const requestId = outputRequestId || masterRequestId
    if (!requestId) return
    const outputs = asRecord(input.outputs)
    const screenplayDraft = asRecord(outputs.screenplayDraft ?? outputs.screenplay_draft)
    const scriptContract = readText(asRecord(screenplayDraft.metadata).scriptContract) || readText(outputs.scriptContract ?? outputs.script_contract)
    const scriptShots = readArray(outputs.scriptShots ?? outputs.script_shots)
    const scriptBlocks = readArray(outputs.scriptBlocks ?? outputs.script_blocks)
    if (scriptContract === 'creative_screenplay_v1' || scriptContract === 'scene_tagged_screenplay_v2' || scriptContract === 'creative_scene_screenplay_v3') {
      const screenplayText = readText(outputs.text) || readText(screenplayDraft.screenplayMarkdown)
      const scriptHash = hashOutputWorkflowValue({
        screenplay: screenplayText,
        scriptContract,
      })
      await insertSequenceAnimaticEvent({
        client: input.client,
        projectId: input.run.projectId,
        draftId: input.run.draftId,
        requestId,
        workflowId: input.workflow.id,
        runId: input.run.id,
        eventType: 'screenplay_ready',
        payload: {
          scriptHash,
          scriptContract,
          screenplayLength: screenplayText.length,
          nodeKey: input.node.key,
          status: input.status,
        },
        metadata: { source: 'cinematic_v3_screenplay_author' },
        dedupe: { scriptHash },
      })
      return
    }
    if (scriptShots.length === 0) return
    const scriptHash = hashOutputWorkflowValue({
      screenplay: readText(outputs.text) || readText(screenplayDraft.screenplayMarkdown),
      scriptShots,
      scriptBlocks,
    })
    await insertSequenceAnimaticEvent({
      client: input.client,
      projectId: input.run.projectId,
      draftId: input.run.draftId,
      requestId,
      workflowId: input.workflow.id,
      runId: input.run.id,
      eventType: 'screenplay_shots_ready',
      payload: {
        shotCount: scriptShots.length,
        blockCount: scriptBlocks.length,
        scriptHash,
        nodeKey: input.node.key,
        status: input.status,
      },
      metadata: { source: 'cinematic_v3_screenplay_author' },
      dedupe: { scriptHash },
    })
    return
  }
  if (role === 'continuity_asset_batch') {
    const batchId = readText(runMetadata.continuityBatchId) || readText(config.continuityBatchId)
    if (!masterRequestId || !batchId) return
    const eventType = input.status === 'completed' && (input.node.key === 'continuity_batch_artifact' || purpose === 'sequence_animatic_continuity_batch_artifact')
      ? 'reference_asset_ready'
      : input.status === 'failed'
        ? 'reference_asset_failed'
        : ''
    if (!eventType) return
    const outputs = asRecord(input.outputs)
    const batch = asRecord(outputs.batch ?? config.batch)
    await insertSequenceAnimaticEvent({
      client: input.client,
      projectId: input.run.projectId,
      draftId: input.run.draftId,
      requestId: masterRequestId,
      workflowId: input.workflow.id,
      runId: input.run.id,
      eventType,
      payload: {
        batchRequestId: readText(runMetadata.outputRequestId),
        batchId,
        batchKind: readText(batch.batchKind) || readText(runMetadata.continuityBatchKind),
        targetNodeIds: readStringArray(batch.targetNodeIds),
        required: runMetadata.continuityBatchRequired === true || batch.required === true,
        readyCount: Object.keys(asRecord(outputs.assetStateByNodeId ?? outputs.asset_state_by_node_id)).length,
        nodeKey: input.node.key,
        status: input.status,
        error: input.errorMessage ?? null,
      },
      metadata: { source: 'sequence_animatic_continuity_batch_workflow' },
      dedupe: { batchId, nodeKey: input.node.key, status: input.status },
    })
    return
  }
  if (role !== 'storyboard_block') return
  const storyboardBlockId = readText(runMetadata.storyboardBlockId) || readText(config.storyboardBlockId)
  if (!masterRequestId || !storyboardBlockId) return
  const eventType = input.status === 'running' && input.node.key === 'block_input'
    ? 'block_started'
    : input.status === 'completed' && (input.node.key === 'storyboard_prompt' || purpose === 'cinematic_v3_storyboard_prompt')
      ? 'storyboard_prompt_ready'
      : input.status === 'completed' && (input.node.key === 'storyboard_sheet' || purpose === 'cinematic_v3_storyboard_sheet')
        ? 'storyboard_sheet_ready'
        : input.status === 'completed' && (input.node.key === 'panel_extract' || purpose === 'cinematic_v3_panel_extract')
          ? 'panels_extracted'
          : input.status === 'completed' && (input.node.key === 'artifact' || purpose === 'sequence_animatic_block_artifact')
            ? 'block_ready'
            : input.status === 'failed'
              ? 'block_failed'
              : ''
  if (!eventType) return
  const outputs = asRecord(input.outputs)
  await insertSequenceAnimaticEvent({
    client: input.client,
    projectId: input.run.projectId,
    draftId: input.run.draftId,
    requestId: masterRequestId,
    workflowId: input.workflow.id,
    runId: input.run.id,
    eventType,
    payload: {
      blockRequestId: readText(runMetadata.outputRequestId),
      storyboardBlockId,
      nodeKey: input.node.key,
      nodeLabel: input.node.label,
      status: input.status,
      panelCount: readArray(outputs.panels).length || readArray(outputs.artifacts).length || null,
      artifactKey: readText(asRecord(outputs.artifact).key) || readText(outputs.artifactKey),
      error: input.errorMessage ?? null,
    },
    metadata: { source: 'sequence_animatic_block_workflow' },
    dedupe: { storyboardBlockId, nodeKey: input.node.key, status: input.status },
  })
}

function readScreenplayAnimaticRoleFromMetadata(metadata: Record<string, unknown>) {
  return readText(metadata.screenplayAnimaticRole) || readText(metadata.sequenceAnimaticRole)
}

function readScreenplayAnimaticSourceFromMetadata(metadata: Record<string, unknown>, fallback: 'wiki_sequence_unit' | 'prompt_cinematic' = 'wiki_sequence_unit') {
  const source = readText(metadata.screenplayAnimaticSource)
  return source === 'prompt_cinematic' || source === 'wiki_sequence_unit' ? source : fallback
}

function sequenceAnimaticBlocksFromManifestAndDirectorPlan(manifest: Record<string, unknown>, directorPlan: Record<string, unknown>) {
  const directorShots = readArray(directorPlan.shots).map(asRecord).filter((shot) => readText(shot.id))
  const directorShotById = new Map(directorShots.map((shot) => [readText(shot.id), shot] as const).filter(([id]) => id))
  const directorBlocks = readArray(directorPlan.blocks).map(asRecord).filter((block) => readText(block.id))
  const directorBlockById = new Map(directorBlocks.map((block) => [readText(block.id), block] as const).filter(([id]) => id))
  return readArray(manifest.blocks).map(asRecord).filter((block) => readText(block.id)).map((block) => {
    const blockId = readText(block.id)
    const directorBlock = directorBlockById.get(blockId) ?? {}
    const manifestShotIds = readStringArray(block.shotIds)
    const directorShotIds = readStringArray(directorBlock.shotIds)
    const shotIds = directorShotIds.length > 0 ? directorShotIds : manifestShotIds
    const manifestShotsById = new Map(readArray(block.shots).map(asRecord).map((shot) => [readText(shot.id), shot] as const).filter(([id]) => id))
    const shots = shotIds
      .map((shotId) => ({ ...asRecord(manifestShotsById.get(shotId)), ...asRecord(directorShotById.get(shotId)), id: shotId }))
      .filter((shot) => readText(shot.id))
    return {
      ...block,
      ...directorBlock,
      id: blockId,
      shotIds: shotIds.length > 0 ? shotIds : readStringArray(block.shotIds),
      shots: shots.length > 0 ? shots : readArray(block.shots).map(asRecord),
      storyboardGroup: asRecord(block.storyboardGroup),
      storyboardLayout: asRecord(block.storyboardLayout),
      durationSeconds: Number(directorBlock.durationSeconds ?? block.durationSeconds ?? 0) || Number(block.durationSeconds ?? 0) || undefined,
    }
  })
}

function sequenceAnimaticBatchLayout(count: number) {
  const safeCount = Math.max(1, Math.min(9, Math.floor(count) || 1))
  if (safeCount <= 1) return { rows: 1, columns: 1, cellCount: 1 }
  if (safeCount <= 2) return { rows: 1, columns: 2, cellCount: safeCount }
  if (safeCount <= 4) return { rows: 2, columns: 2, cellCount: safeCount }
  if (safeCount <= 6) return { rows: 2, columns: 3, cellCount: safeCount }
  return { rows: 3, columns: 3, cellCount: safeCount }
}

function sequenceAnimaticContinuityNodeCollections(graphInput: unknown) {
  const graph = asRecord(graphInput)
  return [
    ...readArray(graph.locationSets ?? graph.location_sets).map((entry) => ({ ...asRecord(entry), nodeKind: 'location_set', assetKind: 'location_zone' })),
    ...readArray(graph.zones).map((entry) => ({ ...asRecord(entry), nodeKind: 'location_zone', assetKind: 'location_zone' })),
    ...readArray(graph.spots).map((entry) => ({ ...asRecord(entry), nodeKind: 'location_spot', assetKind: 'location_spot' })),
    ...readArray(graph.viewpoints).map((entry) => ({ ...asRecord(entry), nodeKind: 'location_viewpoint', assetKind: 'location_angle' })),
    ...readArray(graph.angles).map((entry) => ({ ...asRecord(entry), nodeKind: 'location_angle', assetKind: 'location_angle' })),
    ...readArray(graph.assetAnchors ?? graph.asset_anchors).map((entry) => {
      const record = asRecord(entry)
      const type = readText(record.type) || readText(record.anchorType)
      return {
        ...record,
        nodeKind: type === 'character' ? 'temporary_character' : type === 'prop' ? 'prop' : readText(record.nodeKind) || 'location_anchor',
        assetKind: type === 'character' ? 'temporary_character' : type === 'prop' ? 'prop' : 'location_spot',
      }
    }),
  ].filter((entry) => readText(entry.id))
}

function sequenceAnimaticNodeRequiredMap(requirementsInput: unknown) {
  const map = new Map<string, { required: boolean; assetType: string; priority: string; worldReferenceAssetKeys: string[] }>()
  for (const requirement of readArray(requirementsInput).map(asRecord)) {
    const nodeId = readText(requirement.sceneGraphNodeId ?? requirement.nodeId ?? requirement.id)
    if (!nodeId) continue
    const previous = map.get(nodeId)
    map.set(nodeId, {
      required: previous?.required === true || requirement.required === true || readText(requirement.priority) === 'required',
      assetType: readText(requirement.assetType ?? requirement.type) || previous?.assetType || '',
      priority: readText(requirement.priority) || previous?.priority || '',
      worldReferenceAssetKeys: [...new Set([
        ...(previous?.worldReferenceAssetKeys ?? []),
        ...readStringArray(requirement.worldReferenceAssetKeys ?? requirement.referenceAssetKeys),
      ])],
    })
  }
  return map
}

function sequenceAnimaticNodeBlockIds(node: Record<string, unknown>, shotBindings: Record<string, unknown>) {
  const ids = new Set(readStringArray(node.blockIds))
  for (const shotId of readStringArray(node.shotIds)) {
    const binding = asRecord(shotBindings[shotId])
    const blockId = readText(binding.storyboardBlockId)
    if (blockId) ids.add(blockId)
  }
  return [...ids]
}

function sequenceAnimaticWorldReferenceAssetKeysForNode(node: Record<string, unknown>, assetPack: Record<string, unknown>) {
  const worldKey = readText(node.worldLocationRefId) || readText(node.baseLocationRefId) || readText(node.worldRefId) || readText(node.worldEntityKey)
  if (!worldKey) return []
  const entity = readArray(assetPack.entities).map(asRecord).find((entry) => readText(entry.key) === worldKey) ?? null
  if (!entity) return []
  return [...new Set([
    readText(entity.primaryAssetKey),
    readText(entity.selectedReferenceAssetKey),
    ...readStringArray(entity.assetKeys),
  ].filter(Boolean))].slice(0, 3)
}

function sequenceAnimaticContinuityAssetBatches(input: {
  directorPlan: Record<string, unknown>
  manifest: Record<string, unknown>
}) {
  const graph = asRecord(input.directorPlan.continuityGraphV2 ?? input.directorPlan.continuity_graph_v2)
  const assetPack = asRecord(input.manifest.assetPack)
  const shotBindings = asRecord(input.directorPlan.shotBindings ?? input.directorPlan.shot_bindings ?? graph.shotBindings)
  const requiredByNode = sequenceAnimaticNodeRequiredMap(input.directorPlan.assetRequirements ?? input.directorPlan.asset_requirements)
  const targets = sequenceAnimaticContinuityNodeCollections(graph)
    .filter((node) => requiredByNode.has(readText(node.id)) || readText(node.assetRequired) === 'true' || node.assetRequired === true || node.required === true)
  const byId = new Map(targets.map((node) => [readText(node.id), node] as const).filter(([id]) => id))
  const batches: Record<string, unknown>[] = []
  const pushBatch = (kind: string, nodes: Record<string, unknown>[], sourceReferenceNodeIds: string[] = []) => {
    const cleanNodes = nodes.filter((node) => readText(node.id))
    if (cleanNodes.length === 0) return
    const targetNodeIds = cleanNodes.map((node) => readText(node.id)).filter(Boolean)
    const requirementInfo = targetNodeIds.map((id) => requiredByNode.get(id)).filter(Boolean)
    const required = requirementInfo.some((entry) => entry?.required === true)
    const blockIds = [...new Set(cleanNodes.flatMap((node) => sequenceAnimaticNodeBlockIds(node, shotBindings)))]
    const worldReferenceAssetKeys = [...new Set([
      ...cleanNodes.flatMap((node) => sequenceAnimaticWorldReferenceAssetKeysForNode(node, assetPack)),
      ...requirementInfo.flatMap((entry) => entry?.worldReferenceAssetKeys ?? []),
    ])].slice(0, 8)
    batches.push({
      batchId: `batch_${slugify(kind)}_${sequenceAnimaticStableHash({ kind, targetNodeIds }).slice(0, 8)}`,
      batchKind: kind,
      targetNodeIds,
      sourceReferenceNodeIds: [...new Set(sourceReferenceNodeIds.filter(Boolean))],
      worldReferenceAssetKeys,
      blockIds,
      layout: sequenceAnimaticBatchLayout(kind === 'single_hero_ref' || kind === 'location_zone_board' ? 1 : cleanNodes.length),
      required,
      targetNodes: cleanNodes,
    })
  }
  const setsAndZones = targets.filter((node) => ['location_set', 'location_zone'].includes(readText(node.nodeKind)))
  for (const node of setsAndZones) pushBatch('location_zone_board', [node], [readText(node.worldLocationRefId)].filter(Boolean))
  const anglesByZone = new Map<string, Record<string, unknown>[]>()
  targets.filter((node) => readText(node.nodeKind) === 'location_angle' || readText(node.nodeKind) === 'location_viewpoint').forEach((node) => {
    const zoneId = readText(node.zoneId) || readText(node.setId) || 'global'
    anglesByZone.set(zoneId, [...(anglesByZone.get(zoneId) ?? []), node])
  })
  anglesByZone.forEach((nodes, zoneId) => {
    nodes.length === 1 ? pushBatch('single_hero_ref', nodes, [zoneId]) : pushBatch('angle_grid', nodes, [zoneId])
  })
  const spotsByZone = new Map<string, Record<string, unknown>[]>()
  targets.filter((node) => readText(node.nodeKind) === 'location_spot').forEach((node) => {
    const zoneId = readText(node.zoneId) || 'global'
    spotsByZone.set(zoneId, [...(spotsByZone.get(zoneId) ?? []), node])
  })
  spotsByZone.forEach((nodes, zoneId) => {
    nodes.length === 1 ? pushBatch('single_hero_ref', nodes, [zoneId]) : pushBatch('spot_grid', nodes, [zoneId])
  })
  const anchors = targets.filter((node) => ['temporary_character', 'prop'].includes(readText(node.nodeKind)) || ['temporary_character', 'prop'].includes(readText(node.assetKind)))
  const groupedAnchors = new Map<string, Record<string, unknown>[]>()
  anchors.forEach((node) => {
    const kind = readText(node.assetKind) === 'temporary_character' || readText(node.nodeKind) === 'temporary_character' ? 'temp_character_grid' : 'prop_grid'
    const blockKey = sequenceAnimaticNodeBlockIds(node, shotBindings).join('_') || 'global'
    const key = `${kind}:${blockKey}`
    groupedAnchors.set(key, [...(groupedAnchors.get(key) ?? []), node])
  })
  groupedAnchors.forEach((nodes, key) => {
    const kind = key.startsWith('temp_character_grid:') ? 'temp_character_grid' : 'prop_grid'
    const heroNodes = nodes.filter((node) => readStringArray(node.shotIds).length >= 3 || readText(node.importance) === 'hero' || readText(node.priority) === 'hero')
    heroNodes.forEach((node) => pushBatch('single_hero_ref', [node]))
    const incidental = nodes.filter((node) => !heroNodes.includes(node))
    for (let index = 0; index < incidental.length; index += 6) {
      const slice = incidental.slice(index, index + 6)
      slice.length === 1 ? pushBatch('single_hero_ref', slice) : pushBatch(kind, slice)
    }
  })
  return batches.filter((batch, index, list) => {
    const ids = readStringArray(batch.targetNodeIds).join('|')
    return list.findIndex((candidate) => readStringArray(candidate.targetNodeIds).join('|') === ids) === index
  })
}

function sequenceAnimaticContinuityAssetEntityFromState(stateInput: unknown) {
  const state = asRecord(stateInput)
  const assetKey = readText(state.assetKey)
  const sourceNodeId = readText(state.sourceNodeId)
  if (!assetKey || !sourceNodeId || readText(state.status) !== 'ready') return null
  const assetKind = readText(state.assetKind) || 'continuity_asset'
  return {
    key: `continuity_ref_${slugify(sourceNodeId)}`,
    name: readText(state.name) || titleFromRefLike(sourceNodeId),
    type: assetKind === 'location_angle' || assetKind === 'location_zone' || assetKind === 'location_spot' ? 'location_spot' : assetKind === 'temporary_character' ? 'character' : assetKind === 'prop' ? 'prop' : 'continuity_asset',
    role: 'continuity_reference',
    summary: readText(state.summary) || 'Animatic-specific scene graph reference generated for continuity.',
    visualDescription: 'Use this generated animatic scene-graph reference to preserve spatial layout, materials, camera setup, identity, and prop design.',
    assetKeys: [assetKey],
    primaryAssetKey: assetKey,
    selectedReferenceAssetKey: assetKey,
    selectedReferenceVariantKey: 'continuity_asset',
    selectedReferenceVariantLabel: readText(state.name) || titleFromRefLike(sourceNodeId),
    selectedReferenceVariantType: 'continuity_asset',
    referenceSelectionReason: `Ready continuity asset for scene graph node ${sourceNodeId}.`,
    continuitySourceNodeId: sourceNodeId,
  }
}

async function augmentStoryboardBlockWorkflowAssetPackWithContinuityAssets(input: {
  client: DatabaseClient
  request: OutputRequest
  workflowId: string
}) {
  const requestMetadata = asRecord(input.request.metadata)
  if (readScreenplayAnimaticRoleFromMetadata(requestMetadata) !== 'storyboard_block') return
  const masterRequestId = readText(requestMetadata.masterRequestId) || readText(requestMetadata.parentRequestId) || input.request.parentRequestId
  if (!masterRequestId) return
  const artifactResponse = await input.client
    .from('output_artifacts')
    .select(outputArtifactSelect)
    .eq('project_id', input.request.projectId)
    .eq('draft_id', input.request.draftId)
    .order('created_at', { ascending: false })
    .limit(500)
  if (artifactResponse.error) throw new Error(artifactResponse.error.message)
  const continuityEntities = (artifactResponse.data ?? [])
    .map((row) => asRecord(asRecord(row).metadata))
    .filter((metadata) => (readText(metadata.role) === 'sequence_animatic_continuity_asset' || readText(metadata.role) === 'sequence_animatic_continuity_asset_batch') && readText(metadata.masterRequestId) === masterRequestId)
    .flatMap((metadata) => {
      if (readText(metadata.role) === 'sequence_animatic_continuity_asset_batch') {
        return Object.values(asRecord(metadata.assetStateByNodeId ?? metadata.asset_state_by_node_id)).map((state) => sequenceAnimaticContinuityAssetEntityFromState(state))
      }
      return [sequenceAnimaticContinuityAssetEntityFromState(metadata.assetState ?? metadata.asset_state)]
    })
    .filter((entry): entry is Record<string, unknown> => Boolean(entry))
  if (continuityEntities.length === 0) return
  const nodeResponse = await input.client
    .from('output_workflow_nodes')
    .select(outputWorkflowNodeSelect)
    .eq('workflow_id', input.workflowId)
    .eq('key', 'block_input')
    .maybeSingle()
  if (nodeResponse.error) throw new Error(nodeResponse.error.message)
  if (!nodeResponse.data) return
  const node = mapOutputWorkflowNodeRow(nodeResponse.data)
  const config = asRecord(node.config)
  const assetPack = asRecord(config.assetPack)
  const existingEntities = readArray(assetPack.entities).map(asRecord)
  const existingKeys = new Set(existingEntities.map((entity) => readText(entity.key)).filter(Boolean))
  const mergedContinuityEntities = continuityEntities.filter((entity) => {
    const key = readText(entity.key)
    if (!key || existingKeys.has(key)) return false
    existingKeys.add(key)
    return true
  })
  if (mergedContinuityEntities.length === 0) return
  const nextAssetPack = {
    ...assetPack,
    entities: [...existingEntities, ...mergedContinuityEntities].slice(0, 32),
    continuityReferenceAssetKeys: [...new Set([
      ...readStringArray(assetPack.continuityReferenceAssetKeys),
      ...mergedContinuityEntities.map((entity) => readText(entity.primaryAssetKey)).filter(Boolean),
    ])],
  }
  await input.client
    .from('output_workflow_nodes')
    .update({
      config: {
        ...config,
        assetPack: nextAssetPack,
        asset_pack: nextAssetPack,
      },
    })
    .eq('id', node.id)
}

async function startSequenceAnimaticChildRun(input: {
  client: DatabaseClient
  request: OutputRequest
  workflowId: string
  runIntent: 'prepare_storyboard_block' | 'generate_continuity_asset' | 'generate_scene_shot_plan'
  targetNodeKeys: string[]
}) {
  await augmentStoryboardBlockWorkflowAssetPackWithContinuityAssets({
    client: input.client,
    request: input.request,
    workflowId: input.workflowId,
  })
  const existingRunId = readText(input.request.latestRunId)
  if (existingRunId) {
    const existingRunResponse = await input.client
      .from('output_workflow_runs')
      .select('id,status')
      .eq('id', existingRunId)
      .maybeSingle()
    if (existingRunResponse.error) throw new Error(existingRunResponse.error.message)
    const status = readText(asRecord(existingRunResponse.data).status)
    if (status === 'queued' || status === 'running' || status === 'completed') {
      return { started: false, runId: existingRunId, status }
    }
  }
  const [workflowResponse, nodeResponse, edgeResponse] = await Promise.all([
    input.client
      .from('output_workflows')
      .select(outputWorkflowSelect)
      .eq('id', input.workflowId)
      .single(),
    input.client
      .from('output_workflow_nodes')
      .select(outputWorkflowNodeSelect)
      .eq('workflow_id', input.workflowId)
      .order('created_at', { ascending: true }),
    input.client
      .from('output_workflow_edges')
      .select(outputWorkflowEdgeSelect)
      .eq('workflow_id', input.workflowId)
      .order('created_at', { ascending: true }),
  ])
  if (workflowResponse.error || !workflowResponse.data) throw new Error(workflowResponse.error?.message ?? 'Child workflow not found.')
  if (nodeResponse.error) throw new Error(nodeResponse.error.message)
  if (edgeResponse.error) throw new Error(edgeResponse.error.message)
  const workflow = mapOutputWorkflowRow(workflowResponse.data)
  const nodes = (nodeResponse.data ?? []).map(mapOutputWorkflowNodeRow)
  const edges = (edgeResponse.data ?? []).map(mapOutputWorkflowEdgeRow)
  const nodeKeySet = new Set(nodes.map((node) => node.key))
  const activeEdges = edges.filter((edge) => nodeKeySet.has(edge.sourceNodeKey) && nodeKeySet.has(edge.targetNodeKey))
  const validation = validateOutputWorkflowGraph({ nodes, edges: activeEdges })
  if (!validation.ok) throw new Error(validation.diagnostics.join(' '))
  const intentDefaults = outputWorkflowRunIntentDefaults(input.runIntent)
  const requestMetadata = asRecord(input.request.metadata)
  const metadata = {
    runIntent: input.runIntent,
    runScope: intentDefaults?.runScope ?? 'upstream_to_node',
    debugSkipVideoGeneration: intentDefaults?.debugSkipVideoGeneration ?? true,
    cinematicVideoApproved: intentDefaults?.cinematicVideoApproved ?? false,
    allowStaleUpstreamOutputs: intentDefaults?.allowStaleUpstreamOutputs ?? false,
    targetNodeKeys: input.targetNodeKeys,
    parentRequestId: readText(requestMetadata.parentRequestId) || input.request.parentRequestId,
    masterRequestId: readText(requestMetadata.masterRequestId) || readText(requestMetadata.parentRequestId) || input.request.parentRequestId,
    storyboardBlockId: readText(requestMetadata.storyboardBlockId),
    outputRequestId: input.request.id,
    queuedAt: new Date().toISOString(),
    startedBy: 'sequence_animatic_orchestrator',
  }
  const selectedSubgraph = selectOutputWorkflowRunSubgraph({
    nodes,
    edges: activeEdges,
    targetNodeKeys: input.targetNodeKeys,
    runScope: 'upstream_to_node',
  })
  if (selectedSubgraph.diagnostics.length > 0) throw new Error(selectedSubgraph.diagnostics.join(' '))
  const executionPlan = buildOutputWorkflowExecutionPlan(selectedSubgraph.nodes, selectedSubgraph.edges)
  const nodeOrder = new Map(executionPlan.orderedNodeKeys.map((key, index) => [key, index]))
  const executionLevelByNodeKey = new Map(executionPlan.levels.flatMap((level, index) => level.map((key) => [key, index] as const)))
  const runInput = {
    sourceEntityKeys: input.request.selectedEntityKeys,
    sourceSequenceUnitKeys: input.request.selectedSequenceUnitKeys,
    masterRequestId: readText(metadata.masterRequestId),
    storyboardBlockId: readText(metadata.storyboardBlockId),
  }
  const now = new Date().toISOString()
  const runResponse = await input.client
    .from('output_workflow_runs')
    .insert({
      project_id: input.request.projectId,
      draft_id: input.request.draftId,
      workflow_id: input.workflowId,
      requested_by: input.request.requestedBy,
      status: 'queued',
      preset: workflow.preset,
      prompt: input.request.prompt,
      target_format: input.request.targetFormat,
      world_snapshot_fingerprint: buildOutputWorkflowInputFingerprint(runInput),
      input: runInput,
      metadata,
      heartbeat_at: now,
    })
    .select(outputWorkflowRunSelect)
    .single()
  if (runResponse.error || !runResponse.data) throw new Error(runResponse.error?.message ?? 'Failed to queue child output workflow run.')
  const runRow = runResponse.data
  const stepResponse = await input.client
    .from('output_workflow_run_steps')
    .insert(selectedSubgraph.nodes
      .slice()
      .sort((left, right) => (nodeOrder.get(left.key) ?? 999) - (nodeOrder.get(right.key) ?? 999))
      .map((node, index) => ({
        run_id: runRow.id,
        workflow_id: input.workflowId,
        node_id: node.id,
        draft_id: input.request.draftId,
        node_key: node.key,
        node_type: node.nodeType,
        status: 'queued',
        order_index: index,
        label: node.label,
        metadata: {
          executionLevel: executionLevelByNodeKey.get(node.key) ?? 0,
          resourceClass: getOutputWorkflowNodeExecutionMetadata(node).resourceClass,
          groupKey: getOutputWorkflowNodeExecutionMetadata(node).groupKey ?? null,
          runScope: metadata.runScope,
          outputRequestId: input.request.id,
        },
      })))
    .select(outputWorkflowRunStepSelect)
  if (stepResponse.error) throw new Error(stepResponse.error.message)
  const updateRequest = await input.client
    .from('output_requests')
    .update({
      latest_run_id: runRow.id,
      status: 'running',
      error_message: null,
      metadata: {
        ...requestMetadata,
        readyToRun: false,
        latestRunId: runRow.id,
        lastRunStartedAt: now,
        startedBy: 'sequence_animatic_orchestrator',
      },
    })
    .eq('id', input.request.id)
  if (updateRequest.error) throw new Error(updateRequest.error.message)
  await input.client.rpc('refresh_output_request_status_projection', { p_request_id: input.request.id })
  await notifyWorkerWakeBestEffort({
    family: 'output_workflow',
    source: 'sequence-animatic-orchestrator',
    runId: readText(runRow.id),
    projectId: input.request.projectId,
    draftId: input.request.draftId,
  })
  return { started: true, runId: readText(runRow.id), status: 'queued' }
}

/**
 * Ensure one scene shot-plan child workflow per registered scene. Each scene is a
 * self-contained mini animatic (own shot plan, director plan, and manifest); no
 * cross-scene merge exists by design. Shared by the worker auto-start hook and
 * the ensure-sequence-animatic-scene-workflows edge function.
 */
export async function ensureSequenceAnimaticSceneShotPlanWorkflows(input: {
  client: DatabaseClient
  masterRequest: OutputRequest
  scenePackageOutput: Record<string, unknown>
  screenplayText: string
  assetPack: Record<string, unknown>
  context: Record<string, unknown>
  guidance: Record<string, unknown>
  maxShotCount: number
  aspectRatio: string
  resolution: string
  sceneIds?: string[]
}): Promise<OutputRequest[]> {
  const masterRequest = input.masterRequest
  const masterMetadata = asRecord(masterRequest.metadata)
  const screenplayAnimaticSource = readText(masterMetadata.screenplayAnimaticSource) === 'prompt_cinematic' ? 'prompt_cinematic' : 'wiki_sequence_unit'
  const parsedPackage = sequenceAnimaticScenePackageOutputSchema.parse(input.scenePackageOutput)
  const scenePackages = (parsedPackage.scenePackages.length > 0 ? parsedPackage.scenePackages : parsedPackage.screenplayScenes)
    .slice()
    .sort((left, right) => (left.index || 9999) - (right.index || 9999))
  if (scenePackages.length === 0) throw new Error('Sequence animatic scene ensure requires registered screenplay scenes.')
  if (!input.screenplayText) throw new Error('Sequence animatic scene ensure requires the authored screenplay text.')
  const existingChildrenResponse = await input.client
    .from('output_requests')
    .select(outputRequestSelect)
    .eq('project_id', masterRequest.projectId)
    .eq('draft_id', masterRequest.draftId)
    .eq('parent_request_id', masterRequest.id)
    .order('created_at', { ascending: true })
  if (existingChildrenResponse.error) throw new Error(existingChildrenResponse.error.message)
  const existingChildren = (existingChildrenResponse.data ?? []).map(mapOutputRequestRow)
  const existingBySceneId = new Map(existingChildren
    .filter((child) => asRecord(child.metadata).sequenceAnimaticStale !== true && readScreenplayAnimaticRoleFromMetadata(asRecord(child.metadata)) === 'scene_shot_plan')
    .map((child) => [readText(asRecord(child.metadata).sceneId), child] as const)
    .filter(([id]) => id))
  const selectedSceneIds = input.sceneIds && input.sceneIds.length > 0 ? new Set(input.sceneIds) : null
  const now = new Date().toISOString()
  const childRequests: OutputRequest[] = []
  for (const scene of scenePackages) {
    const sceneId = readText(scene.sceneId)
    if (!sceneId) continue
    if (selectedSceneIds && !selectedSceneIds.has(sceneId)) {
      const existing = existingBySceneId.get(sceneId)
      if (existing) childRequests.push(existing)
      continue
    }
    const existing = existingBySceneId.get(sceneId)
    if (existing) {
      childRequests.push(existing)
      continue
    }
    const sceneScopedPackageOutput = {
      ...parsedPackage,
      scenePackages: [scene],
      screenplayScenes: [scene],
      dialogueRows: scene.dialogueRows,
    }
    const sceneHash = sequenceAnimaticStableHash({ scene, screenplayLength: input.screenplayText.length })
    const workflowId = crypto.randomUUID()
    const commonConfig = {
      cinematicPipelineVersion: 'v3_script_storyboards',
      graphSpecVersion: 'sequence_animatic_graph_v2',
      screenplayAnimaticRole: 'scene_shot_plan',
      screenplayAnimaticSource,
      sequenceAnimaticRole: 'scene_shot_plan',
      parentRequestId: masterRequest.id,
      masterRequestId: masterRequest.id,
      sceneId,
      sceneIndex: Number(scene.index) || 0,
      sceneTitle: readText(scene.title),
      sceneHash,
      sequenceUnitKey: masterRequest.selectedSequenceUnitKeys[0] ?? null,
      sourceMasterWorkflowId: masterRequest.workflowId,
    }
    const { nodes, edges } = buildSequenceAnimaticSceneWorkflowGraph({
      workflowId,
      draftId: masterRequest.draftId,
      commonConfig,
      sceneId,
      sceneIndex: Number(scene.index) || 0,
      sceneTitle: readText(scene.title),
      scenePackageOutput: sceneScopedPackageOutput,
      screenplayText: input.screenplayText,
      assetPack: input.assetPack,
      context: input.context,
      guidance: input.guidance,
      maxShotCount: input.maxShotCount,
      aspectRatio: input.aspectRatio,
      resolution: input.resolution,
    })
    const workflowPayload = {
      project_id: masterRequest.projectId,
      draft_id: masterRequest.draftId,
      key: `sequence_animatic_scene_${slugify(masterRequest.id)}_${slugify(sceneId)}_${sceneHash.slice(0, 8)}`,
      name: `${masterRequest.title} / Scene ${Number(scene.index) || ''}: ${readText(scene.title) || sceneId}`.trim(),
      description: 'Sequence animatic per-scene shot plan workflow.',
      preset: 'cinematic_episode_from_sequence',
      status: 'active',
      created_by: masterRequest.requestedBy,
      metadata: { ...commonConfig, readyToRun: true },
    }
    const requestPayload = {
      project_id: masterRequest.projectId,
      draft_id: masterRequest.draftId,
      parent_request_id: masterRequest.id,
      requested_by: masterRequest.requestedBy,
      source_surface: screenplayAnimaticSource === 'prompt_cinematic' ? 'outputs' : 'wiki_sequence_unit',
      prompt: `${masterRequest.prompt}\n\nPlan shots and continuity for ${sceneId} (${readText(scene.title) || 'scene'}).`,
      title: `${masterRequest.title} / Scene ${Number(scene.index) || ''}: ${readText(scene.title) || sceneId}`.trim(),
      intent: 'output_generation',
      output_kind: 'cinematic_episode',
      status: 'awaiting_confirmation',
      selected_entity_keys: masterRequest.selectedEntityKeys,
      selected_sequence_unit_keys: masterRequest.selectedSequenceUnitKeys,
      page_count: null,
      target_format: 'video',
      planner_notes: 'Per-scene shot plan workflow prepared from the registered scene index.',
      metadata: {
        ...commonConfig,
        readyToRun: true,
        createdFromSceneIndexAt: now,
      },
    }
    const ensureResponse = await input.client.rpc('ensure_sequence_animatic_child_workflow', {
      p_project_id: masterRequest.projectId,
      p_draft_id: masterRequest.draftId,
      p_parent_request_id: masterRequest.id,
      p_role: 'scene_shot_plan',
      p_identity_key: 'sceneId',
      p_identity_value: sceneId,
      p_workflow: workflowPayload,
      p_nodes: nodes,
      p_edges: edges,
      p_request: requestPayload,
    })
    if (ensureResponse.error || !ensureResponse.data) {
      throw new Error(ensureResponse.error?.message ?? `Failed to ensure scene shot plan workflow for ${sceneId}.`)
    }
    const ensured = asRecord(ensureResponse.data)
    const child = mapOutputRequestRow(asRecord(ensured.request) as never)
    existingBySceneId.set(sceneId, child)
    childRequests.push(child)
  }
  return childRequests.sort((left, right) => (Number(asRecord(left.metadata).sceneIndex ?? 0) || 9999) - (Number(asRecord(right.metadata).sceneIndex ?? 0) || 9999))
}

/**
 * Resolve the manifest + director plan for a sequence-animatic master.
 *
 * Old-style runs registered both on the master workflow. In the per-scene
 * architecture each completed scene child owns its manifest/plan instead, so
 * when the master has none this combines the ready scenes' artifacts at read
 * time (ordered by scene index, ids are scene-scoped and collision-free).
 * Downstream stages (continuity assets, keyframes, storyboards) therefore work
 * over whatever scenes are ready — partial chapters included — without any
 * stored merge step.
 */
export async function resolveSequenceAnimaticCombinedManifest(input: {
  client: DatabaseClient
  masterRequest: OutputRequest
}): Promise<{ manifest: Record<string, unknown>; directorPlan: Record<string, unknown>; manifestArtifactKey: string; readySceneIds: string[] } | null> {
  const childrenResponse = await input.client
    .from('output_requests')
    .select(outputRequestSelect)
    .eq('project_id', input.masterRequest.projectId)
    .eq('draft_id', input.masterRequest.draftId)
    .eq('parent_request_id', input.masterRequest.id)
    .order('created_at', { ascending: true })
  if (childrenResponse.error) throw new Error(childrenResponse.error.message)
  const sceneChildren = (childrenResponse.data ?? []).map(mapOutputRequestRow)
    .filter((child) => readScreenplayAnimaticRoleFromMetadata(asRecord(child.metadata)) === 'scene_shot_plan')
    .filter((child) => child.status === 'completed' && child.workflowId)
    .sort((left, right) => (Number(asRecord(left.metadata).sceneIndex ?? 0) || 9999) - (Number(asRecord(right.metadata).sceneIndex ?? 0) || 9999))
  if (sceneChildren.length === 0) return null
  const workflowIds = sceneChildren.map((child) => child.workflowId).filter((id): id is string => Boolean(id))
  const artifactsResponse = await input.client
    .from('output_artifacts')
    .select(outputArtifactSelect)
    .in('workflow_id', workflowIds)
    .order('created_at', { ascending: false })
  if (artifactsResponse.error) throw new Error(artifactsResponse.error.message)
  const artifactRows = (artifactsResponse.data ?? []).map(asRecord)
  const latestByWorkflowAndRole = new Map<string, Record<string, unknown>>()
  for (const row of artifactRows) {
    const role = readText(asRecord(row.metadata).role)
    const key = `${readText(row.workflow_id)}:${role}`
    if (!latestByWorkflowAndRole.has(key)) latestByWorkflowAndRole.set(key, row)
  }
  const mergeRecordsById = (entries: Record<string, unknown>[]) => {
    const byId = new Map<string, Record<string, unknown>>()
    for (const entry of entries) {
      const id = readText(entry.id)
      if (!id) continue
      byId.set(id, { ...byId.get(id), ...entry })
    }
    return [...byId.values()]
  }
  const blocks: Record<string, unknown>[] = []
  const shots: Record<string, unknown>[] = []
  const planShots: Record<string, unknown>[] = []
  const planBlocks: Record<string, unknown>[] = []
  const coverageSetups: Record<string, unknown>[] = []
  const localReferences: Record<string, unknown>[] = []
  const shotBindings: Record<string, unknown> = {}
  const graphArrays: Record<string, Record<string, unknown>[]> = { sets: [], zones: [], spots: [], viewpoints: [], angles: [], edges: [] }
  const readySceneIds: string[] = []
  const manifestKeys: string[] = []
  let assetPack: Record<string, unknown> = {}
  let blockIndex = 1
  let shotIndex = 1
  for (const child of sceneChildren) {
    const manifestRow = latestByWorkflowAndRole.get(`${child.workflowId}:sequence_animatic_manifest`)
    const planRow = latestByWorkflowAndRole.get(`${child.workflowId}:sequence_animatic_director_plan`)
    const sceneManifest = asRecord(asRecord(manifestRow?.metadata).manifest)
    const scenePlan = asRecord(asRecord(planRow?.metadata).shotContinuityPlan ?? asRecord(planRow?.metadata).directorPlan)
    if (Object.keys(sceneManifest).length === 0) continue
    readySceneIds.push(readText(asRecord(child.metadata).sceneId))
    if (manifestRow) manifestKeys.push(readText(manifestRow.key))
    if (Object.keys(assetPack).length === 0) assetPack = asRecord(sceneManifest.assetPack)
    for (const block of readArray(sceneManifest.blocks).map(asRecord)) {
      blocks.push({ ...block, index: blockIndex })
      blockIndex += 1
    }
    for (const shot of readArray(asRecord(sceneManifest.shotPlan).shots).map(asRecord)) {
      shots.push({ ...shot, index: shotIndex })
      shotIndex += 1
    }
    const planSource = Object.keys(scenePlan).length > 0 ? scenePlan : asRecord(sceneManifest.directorPlan)
    for (const shot of readArray(planSource.shots).map(asRecord)) planShots.push(shot)
    for (const block of readArray(planSource.blocks).map(asRecord)) planBlocks.push(block)
    for (const setup of readArray(planSource.coverageSetups ?? planSource.coverage_setups).map(asRecord)) coverageSetups.push(setup)
    for (const reference of readArray(planSource.localReferences ?? planSource.outputLocalReferences).map(asRecord)) localReferences.push(reference)
    Object.assign(shotBindings, asRecord(planSource.shotBindings ?? planSource.shot_bindings))
    const graph = asRecord(planSource.continuityGraphV2 ?? planSource.continuity_graph_v2 ?? sceneManifest.continuityGraphV2)
    const sceneGraphAdditions = asRecord(planSource.sceneGraphAdditions ?? planSource.scene_graph_additions ?? sceneManifest.sceneGraphAdditions ?? sceneManifest.scene_graph_additions)
    for (const field of Object.keys(graphArrays)) {
      for (const node of readArray(graph[field]).map(asRecord)) graphArrays[field].push(node)
      for (const node of readArray(sceneGraphAdditions[field]).map(asRecord)) graphArrays[field].push(node)
    }
  }
  if (blocks.length === 0 || planShots.length === 0) return null
  const continuityGraphV2 = Object.fromEntries(Object.entries(graphArrays).map(([field, entries]) => [field, mergeRecordsById(entries)]))
  continuityGraphV2.locationSets = mergeRecordsById([
    ...readArray(continuityGraphV2.locationSets).map(asRecord),
    ...readArray(continuityGraphV2.location_sets).map(asRecord),
    ...readArray(continuityGraphV2.sets).map(asRecord),
  ])
  continuityGraphV2.location_sets = continuityGraphV2.locationSets
  const directorPlan = {
    role: 'sequence_animatic_director_plan',
    contractVersion: 'shot_continuity_plan_v2',
    graphSpecVersion: 'sequence_animatic_graph_v2',
    screenplayAnimaticRole: 'director_plan',
    sequenceAnimaticRole: 'director_plan',
    planningMode: 'per_scene_combined',
    combinedFromSceneIds: readySceneIds,
    shots: planShots.map((shot, index) => ({ ...shot, index: index + 1 })),
    blocks: planBlocks.map((block, index) => ({ ...block, index: index + 1 })),
    coverageSetups: mergeRecordsById(coverageSetups),
    localReferences: mergeRecordsById(localReferences),
    shotBindings,
    shot_bindings: shotBindings,
    continuityGraphV2,
    continuity_graph_v2: continuityGraphV2,
  }
  const manifest = {
    role: 'sequence_animatic_manifest',
    graphSpecVersion: 'sequence_animatic_graph_v2',
    sequenceAnimaticRole: 'master',
    screenplayAnimaticRole: 'master',
    requestId: input.masterRequest.id,
    combinedFromSceneIds: readySceneIds,
    provisionalSceneCoverage: true,
    assetPack,
    selectedReferences: assetPack,
    blocks,
    shotPlan: {
      sceneId: 'sequence_animatic_master',
      shots,
      totalEditorialDurationSeconds: shots.reduce((total, shot) => total + (Number(asRecord(shot).editorialDurationSeconds) || 0), 0),
    },
    directorPlan,
    shotContinuityPlan: directorPlan,
    continuityGraphV2,
    continuity_graph_v2: continuityGraphV2,
    shotBindings,
    shot_bindings: shotBindings,
    diagnostics: [`Combined ${readySceneIds.length} ready scene manifest${readySceneIds.length === 1 ? '' : 's'} at read time (per-scene architecture).`],
  }
  return {
    manifest,
    directorPlan,
    manifestArtifactKey: manifestKeys.join('+') || `combined.${input.masterRequest.id.slice(0, 8)}.scene-manifests`,
    readySceneIds,
  }
}

/**
 * After a sequence-animatic master run completes (scenes registered), ensure the
 * per-scene child workflows exist and auto-start only the first scene; the rest
 * are generated on demand from the UI.
 */
async function maybeStartFirstSequenceAnimaticScene(input: {
  client: DatabaseClient
  run: OutputWorkflowRun
  outputsByNodeKey: Record<string, Record<string, unknown>>
}) {
  const registerOutputs = asRecord(input.outputsByNodeKey.sequence_animatic_scene_register)
  if (Object.keys(registerOutputs).length === 0) return null
  const runMetadata = asRecord(input.run.metadata)
  const masterRequestId = readText(runMetadata.outputRequestId) || readText(runMetadata.masterRequestId)
  if (!masterRequestId) return null
  const masterResponse = await input.client
    .from('output_requests')
    .select(outputRequestSelect)
    .eq('id', masterRequestId)
    .single()
  if (masterResponse.error || !masterResponse.data) return null
  const masterRequest = mapOutputRequestRow(masterResponse.data)
  const planningDefaults = asRecord(registerOutputs.planningDefaults)
  const screenplayText = readText(asRecord(input.outputsByNodeKey.cinematic_v3_screenplay_author).text)
  const scenePackageOutput = asRecord(registerOutputs.scenePackage ?? registerOutputs.scene_package)
  const assetPack = asRecord(asRecord(input.outputsByNodeKey.cinematic_v3_reference_select).assetPack
    ?? asRecord(input.outputsByNodeKey.cinematic_v3_reference_select).asset_pack)
  const context = asRecord(asRecord(input.outputsByNodeKey.world_context).context)
  const guidance = asRecord(asRecord(input.outputsByNodeKey.skill_context).guidance)
  if (!screenplayText || Object.keys(scenePackageOutput).length === 0) return null
  const children = await ensureSequenceAnimaticSceneShotPlanWorkflows({
    client: input.client,
    masterRequest,
    scenePackageOutput,
    screenplayText,
    assetPack,
    context,
    guidance,
    maxShotCount: Number(planningDefaults.maxShotCount ?? 0) || 150,
    aspectRatio: readText(planningDefaults.aspectRatio) || '16:9',
    resolution: readText(planningDefaults.resolution) || '720p',
  })
  if (planningDefaults.autoStartFirstScene !== true) return children
  const firstScene = children[0] ?? null
  if (!firstScene?.workflowId) return children
  if (firstScene.status === 'running' || firstScene.status === 'queued' || firstScene.status === 'planning' || firstScene.status === 'completed') return children
  const started = await startSequenceAnimaticChildRun({
    client: input.client,
    request: firstScene,
    workflowId: firstScene.workflowId,
    runIntent: 'generate_scene_shot_plan',
    // Both terminal artifacts: the director-plan artifact is a sibling branch of
    // the manifest artifact and would be excluded by an upstream-only selection.
    targetNodeKeys: ['sequence_animatic_director_plan_artifact', 'artifact'],
  })
  await insertSequenceAnimaticEvent({
    client: input.client,
    projectId: input.run.projectId,
    draftId: input.run.draftId,
    requestId: masterRequest.id,
    workflowId: firstScene.workflowId,
    runId: readText(asRecord(started).runId) || null,
    eventType: 'scene_started',
    payload: {
      sceneId: readText(asRecord(firstScene.metadata).sceneId),
      sceneIndex: Number(asRecord(firstScene.metadata).sceneIndex ?? 0) || 1,
      requestId: firstScene.id,
      autoStarted: true,
    },
    metadata: { source: 'sequence_animatic_scene_auto_start' },
    dedupe: { sceneId: readText(asRecord(firstScene.metadata).sceneId) },
  }).catch(() => null)
  return children
}

async function maybeStartNextSequenceAnimaticStoryboardBlock(input: {
  client: DatabaseClient
  run: OutputWorkflowRun
}) {
  const metadata = asRecord(input.run.metadata)
  const runRole = readText(metadata.screenplayAnimaticRole) || readText(metadata.sequenceAnimaticRole)
  if (runRole !== 'storyboard_block' && runRole !== 'continuity_asset_batch') return null
  const masterRequestId = readText(metadata.masterRequestId) || readText(metadata.parentRequestId)
  if (!masterRequestId) return null
  const childrenResponse = await input.client
    .from('output_requests')
    .select(outputRequestSelect)
    .eq('project_id', input.run.projectId)
    .eq('draft_id', input.run.draftId)
    .eq('parent_request_id', masterRequestId)
    .order('created_at', { ascending: true })
  if (childrenResponse.error) throw new Error(childrenResponse.error.message)
  const allChildren = (childrenResponse.data ?? []).map(mapOutputRequestRow)
    .filter((child) => asRecord(child.metadata).sequenceAnimaticStale !== true)
  const activeRequiredBatches = allChildren.filter((child) => {
    const childMetadata = asRecord(child.metadata)
    return readScreenplayAnimaticRoleFromMetadata(childMetadata) === 'continuity_asset_batch'
      && childMetadata.continuityBatchRequired === true
      && (child.status === 'running' || child.status === 'queued' || child.status === 'planning')
  })
  if (activeRequiredBatches.length > 0) return null
  const children = allChildren
    .filter((child) => readScreenplayAnimaticRoleFromMetadata(asRecord(child.metadata)) === 'storyboard_block')
  const activeChildren = children.filter((child) => child.status === 'running' || child.status === 'queued' || child.status === 'planning')
  if (activeChildren.length > 0) return null
  const nextChild = children
    .filter((child) => child.workflowId)
    .filter((child) => child.status !== 'completed')
    .sort((left, right) => (Number(asRecord(left.metadata).storyboardBlockIndex ?? 0) || 999) - (Number(asRecord(right.metadata).storyboardBlockIndex ?? 0) || 999))[0] ?? null
  if (!nextChild?.workflowId) {
    const masterResponse = await input.client
      .from('output_requests')
      .select('id,metadata')
      .eq('id', masterRequestId)
      .maybeSingle()
    if (masterResponse.error) throw new Error(masterResponse.error.message)
    const masterMetadata = asRecord(asRecord(masterResponse.data).metadata)
    const updateMaster = await input.client
      .from('output_requests')
      .update({
        metadata: {
          ...masterMetadata,
          orchestrationStatus: 'ready',
          orchestrationCompletedAt: new Date().toISOString(),
        },
      })
      .eq('id', masterRequestId)
    if (updateMaster.error) throw new Error(updateMaster.error.message)
    await input.client.rpc('refresh_output_request_status_projection', { p_request_id: masterRequestId })
    return null
  }
  const startResult = await startSequenceAnimaticChildRun({
    client: input.client,
    request: nextChild,
    workflowId: nextChild.workflowId,
    runIntent: 'prepare_storyboard_block',
    targetNodeKeys: ['artifact'],
  })
  if (startResult.started) {
    await insertSequenceAnimaticEvent({
      client: input.client,
      projectId: input.run.projectId,
      draftId: input.run.draftId,
      requestId: masterRequestId,
      workflowId: nextChild.workflowId,
      runId: startResult.runId,
      eventType: 'block_started',
      payload: {
        blockRequestId: nextChild.id,
        workflowId: nextChild.workflowId,
        storyboardBlockId: readText(asRecord(nextChild.metadata).storyboardBlockId),
        runId: startResult.runId,
        status: startResult.status,
      },
      metadata: { source: 'sequence_animatic_orchestrator_continuation' },
      dedupe: { storyboardBlockId: readText(asRecord(nextChild.metadata).storyboardBlockId), runId: startResult.runId },
    })
  }
  return startResult
}

async function runSequenceAnimaticOrchestrator(input: {
  client: DatabaseClient
  run: OutputWorkflowRun
  workflow: OutputWorkflow
  node: OutputWorkflowNode
  upstream: Record<string, unknown>
}) {
  const requestResponse = await input.client
    .from('output_requests')
    .select(outputRequestSelect)
    .eq('draft_id', input.run.draftId)
    .eq('workflow_id', input.workflow.id)
    .order('created_at', { ascending: false })
    .limit(1)
    .maybeSingle()
  if (requestResponse.error) throw new Error(requestResponse.error.message)
  if (!requestResponse.data) throw new Error('Sequence animatic orchestrator could not find the master output request.')
  const masterRequest = mapOutputRequestRow(requestResponse.data)
  const masterMetadata = asRecord(masterRequest.metadata)
  if (readScreenplayAnimaticRoleFromMetadata(masterMetadata) !== 'master') {
    throw new Error('Sequence animatic orchestrator requires a master animatic request.')
  }
  const directorPlan = asRecord(input.upstream.shotContinuityPlan ?? input.upstream.shot_continuity_plan ?? input.upstream.directorPlan ?? input.upstream.director_plan)
  const manifest = asRecord(input.upstream.manifest ?? input.upstream.sequenceAnimaticManifest ?? input.upstream.sequence_animatic_manifest)
  if (Object.keys(directorPlan).length === 0) throw new Error('Sequence animatic orchestrator requires a shot continuity plan.')
  if (Object.keys(manifest).length === 0) throw new Error('Sequence animatic orchestrator requires the master manifest.')
  const blocks = sequenceAnimaticBlocksFromManifestAndDirectorPlan(manifest, directorPlan)
  if (blocks.length === 0) throw new Error('Sequence animatic orchestrator found no storyboard blocks to queue.')
  const screenplayAnimaticSource = readScreenplayAnimaticSourceFromMetadata(
    masterMetadata,
    masterRequest.sourceSurface === 'wiki_sequence_unit' ? 'wiki_sequence_unit' : 'prompt_cinematic',
  )
  const manifestHash = sequenceAnimaticStableHash(manifest)
  const directorPlanHash = readText(directorPlan.shotPlanHash) || sequenceAnimaticStableHash(directorPlan)
  const masterManifestArtifactKey = readText(masterMetadata.masterManifestArtifactKey) || `output.${slugify(input.workflow.name)}.${input.run.id.slice(0, 8)}.sequence-animatic-manifest`
  const existingChildrenResponse = await input.client
    .from('output_requests')
    .select(outputRequestSelect)
    .eq('project_id', input.run.projectId)
    .eq('draft_id', input.run.draftId)
    .eq('parent_request_id', masterRequest.id)
    .order('created_at', { ascending: true })
  if (existingChildrenResponse.error) throw new Error(existingChildrenResponse.error.message)
  const existingChildren = (existingChildrenResponse.data ?? []).map(mapOutputRequestRow)
  const existingByBlockId = new Map(existingChildren
    .filter((child) => asRecord(child.metadata).sequenceAnimaticStale !== true && readScreenplayAnimaticRoleFromMetadata(asRecord(child.metadata)) === 'storyboard_block')
    .map((child) => [readText(asRecord(child.metadata).storyboardBlockId), child] as const)
    .filter(([id]) => id))
  const childRequests: OutputRequest[] = [...existingChildren]
  const now = new Date().toISOString()
  await insertSequenceAnimaticEvent({
    client: input.client,
    projectId: input.run.projectId,
    draftId: input.run.draftId,
    requestId: masterRequest.id,
    workflowId: input.workflow.id,
    runId: input.run.id,
    eventType: 'orchestrator_started',
    payload: { blockCount: blocks.length, directorPlanHash, manifestHash },
    metadata: { source: 'sequence_animatic_orchestrator' },
    dedupe: { directorPlanHash },
  })
  for (const requirement of readArray(directorPlan.assetRequirements ?? directorPlan.asset_requirements).map(asRecord)) {
    await insertSequenceAnimaticEvent({
      client: input.client,
      projectId: input.run.projectId,
      draftId: input.run.draftId,
      requestId: masterRequest.id,
      workflowId: input.workflow.id,
      runId: input.run.id,
      eventType: 'reference_asset_queued',
      payload: {
        sceneGraphNodeId: readText(requirement.sceneGraphNodeId ?? requirement.nodeId ?? requirement.id),
        assetType: readText(requirement.assetType ?? requirement.type),
        priority: readText(requirement.priority),
        required: requirement.required === true,
        reason: readText(requirement.reason),
      },
      metadata: { source: 'sequence_animatic_orchestrator' },
      dedupe: { sceneGraphNodeId: readText(requirement.sceneGraphNodeId ?? requirement.nodeId ?? requirement.id) },
    })
  }
  const continuityAssetBatches = sequenceAnimaticContinuityAssetBatches({ directorPlan, manifest })
  const existingBatchChildren = existingChildren
    .filter((child) => asRecord(child.metadata).sequenceAnimaticStale !== true && readScreenplayAnimaticRoleFromMetadata(asRecord(child.metadata)) === 'continuity_asset_batch')
  const existingBatchById = new Map(existingBatchChildren
    .map((child) => [readText(asRecord(child.metadata).continuityBatchId), child] as const)
    .filter(([id]) => id))
  const batchRequestIds: string[] = []
  const startedBatchRunIds: string[] = []
  for (const batch of continuityAssetBatches) {
    const batchId = readText(batch.batchId)
    if (!batchId) continue
    let child = existingBatchById.get(batchId) ?? null
    const batchHash = sequenceAnimaticStableHash(batch)
    if (!child) {
      const targetNodeIds = readStringArray(batch.targetNodeIds)
      const targetNodes = readArray(batch.targetNodes).map(asRecord).filter((node) => targetNodeIds.includes(readText(node.id)))
      const workflowId = crypto.randomUUID()
      const commonConfig = {
        cinematicPipelineVersion: 'v3_script_storyboards',
        graphSpecVersion: sequenceAnimaticGraphSpecVersion,
        screenplayAnimaticRole: 'continuity_asset_batch',
        screenplayAnimaticSource,
        sequenceAnimaticRole: 'continuity_asset_batch',
        parentRequestId: masterRequest.id,
        masterRequestId: masterRequest.id,
        continuityBatchId: batchId,
        continuityBatchHash: batchHash,
        manifestHash,
        directorPlanHash,
        masterManifestArtifactKey,
        sequenceUnitKey: masterRequest.selectedSequenceUnitKeys[0] ?? null,
      }
      const { nodes, edges } = buildSequenceAnimaticContinuityBatchWorkflowGraph({
        workflowId,
        draftId: input.run.draftId,
        commonConfig,
        batch,
        targetNodes,
        continuityGraphV2: asRecord(directorPlan.continuityGraphV2 ?? directorPlan.continuity_graph_v2),
        relevantShots: readArray(directorPlan.shots).map(asRecord).filter((shot) => readStringArray(batch.blockIds).length === 0 || readStringArray(batch.blockIds).includes(readText(shot.storyboardBlockId))),
        shotBindings: asRecord(directorPlan.shotBindings ?? directorPlan.shot_bindings),
        assetPack: asRecord(manifest.assetPack),
        referenceAssetKeys: readStringArray(batch.worldReferenceAssetKeys),
        visualDependencyEdges: sequenceAnimaticContinuityVisualDependencyEdges(directorPlan.continuityGraphV2 ?? directorPlan.continuity_graph_v2),
        aspectRatio: readText(asRecord(manifest.assetPack).aspectRatio) || '16:9',
      })
      const workflowPayload = {
        project_id: input.run.projectId,
        draft_id: input.run.draftId,
        key: `sequence_animatic_${slugify(masterRequest.id)}_${slugify(batchId)}_${manifestHash.slice(0, 8)}`,
        name: `${masterRequest.title} / ${readText(batch.batchKind) || 'Continuity refs'}`,
        description: 'Sequence animatic continuity reference batch workflow.',
        preset: 'cinematic_episode_from_sequence',
        status: 'active',
        created_by: masterRequest.requestedBy ?? input.run.requestedBy,
        metadata: { ...commonConfig, readyToRun: true },
      }
      const requestPayload = {
        project_id: input.run.projectId,
        draft_id: input.run.draftId,
        parent_request_id: masterRequest.id,
        requested_by: masterRequest.requestedBy ?? input.run.requestedBy,
        source_surface: screenplayAnimaticSource === 'prompt_cinematic' ? 'outputs' : 'wiki_sequence_unit',
        prompt: `${masterRequest.prompt}\n\nGenerate continuity reference batch ${batchId}.`,
        title: `${masterRequest.title} / ${readText(batch.batchKind) || 'Continuity refs'}`,
        intent: 'output_generation',
        output_kind: 'cinematic_episode',
        status: 'awaiting_confirmation',
        selected_entity_keys: masterRequest.selectedEntityKeys,
        selected_sequence_unit_keys: masterRequest.selectedSequenceUnitKeys,
        page_count: null,
        target_format: 'image',
        planner_notes: 'Continuity reference batch prepared by the sequence animatic Fly orchestrator.',
        metadata: {
          ...commonConfig,
          continuityBatchId: batchId,
          continuityBatchHash: batchHash,
          continuityBatchKind: readText(batch.batchKind),
          continuityBatchRequired: batch.required === true,
          targetNodeIds: readStringArray(batch.targetNodeIds),
          blockIds: readStringArray(batch.blockIds),
          batch,
          readyToRun: true,
          createdFromDirectorPlanAt: now,
        },
      }
      const ensureResponse = await input.client.rpc('ensure_sequence_animatic_child_workflow', {
        p_project_id: input.run.projectId,
        p_draft_id: input.run.draftId,
        p_parent_request_id: masterRequest.id,
        p_role: 'continuity_asset_batch',
        p_identity_key: 'continuityBatchId',
        p_identity_value: batchId,
        p_workflow: workflowPayload,
        p_nodes: nodes,
        p_edges: edges,
        p_request: requestPayload,
      })
      if (ensureResponse.error || !ensureResponse.data) throw new Error(ensureResponse.error?.message ?? 'Failed to ensure continuity batch workflow.')
      const ensured = asRecord(ensureResponse.data)
      child = mapOutputRequestRow(asRecord(ensured.request) as never)
      childRequests.push(child)
      existingBatchById.set(batchId, child)
    }
    if (!child) continue
    batchRequestIds.push(child.id)
    await insertSequenceAnimaticEvent({
      client: input.client,
      projectId: input.run.projectId,
      draftId: input.run.draftId,
      requestId: masterRequest.id,
      workflowId: child.workflowId,
      runId: null,
      eventType: 'reference_asset_queued',
      payload: {
        batchId,
        batchKind: readText(batch.batchKind),
        targetNodeIds: readStringArray(batch.targetNodeIds),
        blockIds: readStringArray(batch.blockIds),
        required: batch.required === true,
      },
      metadata: { source: 'sequence_animatic_orchestrator_batch' },
      dedupe: { batchId },
    })
    if (child.workflowId && child.status !== 'running' && child.status !== 'queued' && child.status !== 'completed') {
      const startResult = await startSequenceAnimaticChildRun({
        client: input.client,
        request: child,
        workflowId: child.workflowId,
        runIntent: 'generate_continuity_asset',
        targetNodeKeys: ['continuity_batch_artifact'],
      })
      if (startResult.runId) startedBatchRunIds.push(startResult.runId)
    }
  }
  const queuedBlockRequestIds: string[] = []
  const createdBlockRequestIds: string[] = []
  for (const block of blocks) {
    const blockId = readText(block.id)
    if (!blockId) continue
    let child = existingByBlockId.get(blockId) ?? null
    const blockHash = sequenceAnimaticStableHash(block)
    if (!child) {
      const storyboardGroup = asRecord(block.storyboardGroup)
      const layout = asRecord(block.storyboardLayout)
      const rows = Math.max(1, Number(layout.rows ?? storyboardGroup.rows ?? 1) || 1)
      const columns = Math.max(1, Number(layout.columns ?? storyboardGroup.columns ?? 1) || 1)
      const panelCount = Math.max(1, Number(layout.panelCount ?? storyboardGroup.panelCount ?? readArray(block.shots).length) || 1)
      const aspectRatio = readText(asRecord(manifest.assetPack).aspectRatio) || '16:9'
      const imageSize = sequenceAnimaticStoryboardImageSize(columns, rows, aspectRatio)
      const workflowId = crypto.randomUUID()
      const workflowPayload = {
        project_id: input.run.projectId,
        draft_id: input.run.draftId,
        key: `sequence_animatic_${slugify(masterRequest.id)}_${slugify(blockId)}_${manifestHash.slice(0, 8)}`,
        name: `${masterRequest.title} / Block ${Number(block.index ?? 0) || queuedBlockRequestIds.length + 1}`,
        description: 'Sequence animatic storyboard block workflow.',
        preset: 'cinematic_episode_from_sequence',
        status: 'active',
        created_by: masterRequest.requestedBy ?? input.run.requestedBy,
        metadata: {
          parentRequestId: masterRequest.id,
          masterRequestId: masterRequest.id,
          graphSpecVersion: sequenceAnimaticGraphSpecVersion,
          directorPlanHash,
          screenplayAnimaticRole: 'storyboard_block',
          screenplayAnimaticSource,
          sequenceAnimaticRole: 'storyboard_block',
          storyboardBlockId: blockId,
          manifestHash,
          blockHash,
          masterManifestArtifactKey,
          sequenceUnitKey: masterRequest.selectedSequenceUnitKeys[0] ?? null,
          sourceMasterWorkflowId: input.workflow.id,
          readyToRun: true,
        },
      }
      const blockShotPlan = {
        ...asRecord(manifest.shotPlan),
        totalEditorialDurationSeconds: Number(block.durationSeconds ?? storyboardGroup.editorialDurationSeconds ?? 0) || readArray(block.shots).reduce((total, shot) => total + (Number(asRecord(shot).editorialDurationSeconds ?? 0) || 0), 0),
        shots: readArray(block.shots).map(asRecord),
      }
      const commonConfig = {
        cinematicPipelineVersion: 'v3_script_storyboards',
        graphSpecVersion: sequenceAnimaticGraphSpecVersion,
        screenplayAnimaticRole: 'storyboard_block',
        screenplayAnimaticSource,
        sequenceAnimaticRole: 'storyboard_block',
        parentRequestId: masterRequest.id,
        masterRequestId: masterRequest.id,
        sequenceUnitKey: masterRequest.selectedSequenceUnitKeys[0] ?? null,
        storyboardBlockId: blockId,
        manifestHash,
        blockHash,
        directorPlanHash,
        masterManifestArtifactKey,
      }
      const durationSeconds = Math.max(4, Math.min(15, Number(block.durationSeconds ?? storyboardGroup.providerDurationSeconds ?? 0) || 8))
      const { nodes, edges } = buildSequenceAnimaticBlockWorkflowGraph({
        workflowId,
        draftId: input.run.draftId,
        commonConfig,
        block,
        manifestSummary: {
          title: readText(manifest.title) || masterRequest.title,
          screenplayMarkdown: readText(manifest.screenplayMarkdown),
        },
        shotPlan: blockShotPlan,
        storyboardGroup,
        storyboardLayout: { rows, columns, panelCount },
        assetPack: asRecord(manifest.assetPack),
        aspectRatio,
        imageSize,
        durationSeconds,
      })
      const requestPayload = {
        project_id: input.run.projectId,
        draft_id: input.run.draftId,
        parent_request_id: masterRequest.id,
        requested_by: masterRequest.requestedBy ?? input.run.requestedBy,
        source_surface: screenplayAnimaticSource === 'prompt_cinematic' ? 'outputs' : 'wiki_sequence_unit',
        prompt: `${masterRequest.prompt}\n\nStoryboard block ${Number(block.index ?? 0) || queuedBlockRequestIds.length + 1}: ${readText(block.title) || blockId}`,
        title: `${masterRequest.title} / Block ${Number(block.index ?? 0) || queuedBlockRequestIds.length + 1}`,
        intent: 'output_generation',
        output_kind: 'cinematic_episode',
        status: 'awaiting_confirmation',
        selected_entity_keys: masterRequest.selectedEntityKeys,
        selected_sequence_unit_keys: masterRequest.selectedSequenceUnitKeys,
        page_count: null,
        target_format: 'video',
        planner_notes: 'Storyboard block graph prepared by the sequence animatic Fly orchestrator.',
        metadata: {
          graphSpecVersion: sequenceAnimaticGraphSpecVersion,
          directorPlanHash,
          screenplayAnimaticRole: 'storyboard_block',
          screenplayAnimaticSource,
          sequenceAnimaticRole: 'storyboard_block',
          parentRequestId: masterRequest.id,
          masterRequestId: masterRequest.id,
          storyboardBlockId: blockId,
          storyboardBlockIndex: Number(block.index ?? 0) || queuedBlockRequestIds.length + 1,
          manifestHash,
          blockHash,
          masterManifestArtifactKey,
          sequenceUnitKey: masterRequest.selectedSequenceUnitKeys[0] ?? null,
          sourceMasterWorkflowId: input.workflow.id,
          readyToRun: true,
          createdFromManifestAt: now,
          block,
        },
      }
      const ensureResponse = await input.client.rpc('ensure_sequence_animatic_child_workflow', {
        p_project_id: input.run.projectId,
        p_draft_id: input.run.draftId,
        p_parent_request_id: masterRequest.id,
        p_role: 'storyboard_block',
        p_identity_key: 'storyboardBlockId',
        p_identity_value: blockId,
        p_workflow: workflowPayload,
        p_nodes: nodes,
        p_edges: edges,
        p_request: requestPayload,
      })
      if (ensureResponse.error || !ensureResponse.data) throw new Error(ensureResponse.error?.message ?? 'Failed to ensure storyboard block workflow.')
      const ensured = asRecord(ensureResponse.data)
      child = mapOutputRequestRow(asRecord(ensured.request) as never)
      childRequests.push(child)
      existingByBlockId.set(blockId, child)
      if (ensured.created === true) createdBlockRequestIds.push(child.id)
    }
    if (!child) continue
    queuedBlockRequestIds.push(child.id)
    await insertSequenceAnimaticEvent({
      client: input.client,
      projectId: input.run.projectId,
      draftId: input.run.draftId,
      requestId: masterRequest.id,
      workflowId: child.workflowId,
      runId: null,
      eventType: 'block_queued',
      payload: {
        blockRequestId: child.id,
        workflowId: child.workflowId,
        storyboardBlockId: blockId,
        blockHash,
        directorPlanHash,
        title: readText(block.title) || child.title,
        shotIds: readStringArray(block.shotIds),
        created: createdBlockRequestIds.includes(child.id),
      },
      metadata: { source: 'sequence_animatic_orchestrator' },
      dedupe: { storyboardBlockId: blockId },
    })
  }
  const activeBlockRuns = childRequests.filter((child) => {
    const role = readScreenplayAnimaticRoleFromMetadata(asRecord(child.metadata))
    return role === 'storyboard_block' && (child.status === 'running' || child.status === 'queued' || child.status === 'planning')
  })
  const activeRequiredBatchRuns = childRequests.filter((child) => {
    const metadata = asRecord(child.metadata)
    const role = readScreenplayAnimaticRoleFromMetadata(metadata)
    return role === 'continuity_asset_batch' && metadata.continuityBatchRequired === true && (child.status === 'running' || child.status === 'queued' || child.status === 'planning')
  })
  const blockConcurrency = Math.max(1, Number(asRecord(input.node.config).blockConcurrency ?? 1) || 1)
  const startableChildren = childRequests
    .filter((child) => readScreenplayAnimaticRoleFromMetadata(asRecord(child.metadata)) === 'storyboard_block')
    .filter((child) => child.workflowId)
    .filter((child) => child.status !== 'running' && child.status !== 'queued' && child.status !== 'completed')
    .sort((left, right) => (Number(asRecord(left.metadata).storyboardBlockIndex ?? 0) || 999) - (Number(asRecord(right.metadata).storyboardBlockIndex ?? 0) || 999))
  const startedRunIds: string[] = []
  const startSlots = activeRequiredBatchRuns.length > 0 || startedBatchRunIds.length > 0 ? 0 : Math.max(0, blockConcurrency - activeBlockRuns.length)
  for (const child of startableChildren.slice(0, startSlots)) {
    if (!child.workflowId) continue
    const startResult = await startSequenceAnimaticChildRun({
      client: input.client,
      request: child,
      workflowId: child.workflowId,
      runIntent: 'prepare_storyboard_block',
      targetNodeKeys: ['artifact'],
    })
    if (startResult.runId) startedRunIds.push(startResult.runId)
    if (startResult.started) {
      await insertSequenceAnimaticEvent({
        client: input.client,
        projectId: input.run.projectId,
        draftId: input.run.draftId,
        requestId: masterRequest.id,
        workflowId: child.workflowId,
        runId: startResult.runId,
        eventType: 'block_started',
        payload: {
          blockRequestId: child.id,
          workflowId: child.workflowId,
          storyboardBlockId: readText(asRecord(child.metadata).storyboardBlockId),
          runId: startResult.runId,
          status: startResult.status,
        },
        metadata: { source: 'sequence_animatic_orchestrator' },
        dedupe: { storyboardBlockId: readText(asRecord(child.metadata).storyboardBlockId), runId: startResult.runId },
      })
    }
  }
  const updateMaster = await input.client
    .from('output_requests')
    .update({
      metadata: {
        ...masterMetadata,
        screenplayAnimaticRole: 'master',
        sequenceAnimaticRole: 'master',
        graphSpecVersion: 'sequence_animatic_graph_v2',
        directorPlanHash,
        orchestrationStatus: startableChildren.length > startSlots ? 'partial' : 'queued',
        orchestrationUpdatedAt: new Date().toISOString(),
        childBlockRequestIds: queuedBlockRequestIds,
        continuityBatchRequestIds: batchRequestIds,
        childBlockWorkflowIds: childRequests.map((child) => child.workflowId).filter(Boolean),
        activeStoryboardBlockRunIds: startedRunIds,
        activeContinuityBatchRunIds: startedBatchRunIds,
      },
    })
    .eq('id', masterRequest.id)
  if (updateMaster.error) throw new Error(updateMaster.error.message)
  await input.client.rpc('refresh_output_request_status_projection', { p_request_id: masterRequest.id })
  return {
    orchestration: {
      status: startableChildren.length > startSlots ? 'partial' : 'queued',
      blockCount: blocks.length,
      queuedBlockCount: queuedBlockRequestIds.length,
      startedRunCount: startedRunIds.length,
      startedBatchRunCount: startedBatchRunIds.length,
      activeBlockRunCount: activeBlockRuns.length + startedRunIds.length,
      activeRequiredBatchRunCount: activeRequiredBatchRuns.length + startedBatchRunIds.length,
      blockConcurrency,
      directorPlanHash,
      manifestHash,
      continuityAssetBatchCount: continuityAssetBatches.length,
    },
    childRequests: childRequests.map((child) => ({
      id: child.id,
      workflowId: child.workflowId,
      status: child.status,
      storyboardBlockId: readText(asRecord(child.metadata).storyboardBlockId),
      title: child.title,
    })),
    startedRunIds,
  }
}

function mergeComicSelectedEntitiesWithFallback(selectedEntities: Array<Record<string, unknown>>, fallbackPack: Record<string, unknown>) {
  const fallbackEntities = Array.isArray(fallbackPack.entities) ? fallbackPack.entities.map(asRecord) : []
  const fallbackByKey = new Map(fallbackEntities.map((entity) => [readText(entity.key), entity]).filter(([key]) => key))
  const merged = selectedEntities.length > 0 ? selectedEntities : fallbackEntities
  return merged.map((entity) => {
    const key = readText(entity.key)
    const fallback = fallbackByKey.get(key) ?? {}
    const assetKeys = [
      ...readStringArray(fallback.assetKeys),
      ...readStringArray(entity.assetKeys),
    ]
    const fallbackVisualDescription = readText(fallback.visualDescription)
    const visualTraits = [
      ...readStringArray(fallback.visualTraits),
      ...readStringArray(entity.visualTraits),
    ]
    const fallbackTraitMap = asRecord(fallback.visualTraitMap)
    const entityTraitMap = asRecord(entity.visualTraitMap)
    return {
      key,
      name: readText(entity.name) || readText(fallback.name),
      type: readText(entity.type) || readText(fallback.type),
      role: readText(entity.role) || readText(fallback.role) || readText(entity.type) || readText(fallback.type),
      summary: readText(entity.summary) || readText(fallback.summary),
      visualDescription: fallbackVisualDescription || readText(entity.visualDescription),
      visualTraits: [...new Set(visualTraits)].filter(Boolean),
      visualTraitMap: { ...fallbackTraitMap, ...entityTraitMap },
      assetKeys: [...new Set(assetKeys)].filter(Boolean),
    }
  }).filter((entity) => entity.key || entity.name).slice(0, 16)
}

export function buildDeterministicCinematicAssetPack(context: Record<string, unknown>) {
  return buildDeterministicComicAssetPack(context)
}

function cinematicAssetPackEntities(assetPack: Record<string, unknown>) {
  return Array.isArray(assetPack.entities) ? assetPack.entities.map(asRecord) : []
}

function cinematicAssetPackEntityKeys(assetPack: Record<string, unknown>) {
  return cinematicAssetPackEntities(assetPack).map((entity) => readText(entity.key)).filter(Boolean)
}

function referencePlanKeys(plan: Record<string, unknown>) {
  return [...new Set([
    ...readStringArray(plan.primaryCastRefIds),
    ...readStringArray(plan.supportingCastRefIds),
    ...readStringArray(plan.locationRefIds),
    ...readStringArray(plan.propRefIds),
    ...readStringArray(plan.conceptRefIds),
    ...readStringArray(plan.continuityAnchorRefIds),
  ].filter(Boolean))]
}

function cloneCinematicAssetPackEntity(entity: Record<string, unknown>, maxAssetKeys = 2) {
  const selectedReferenceVariantAssetKey = selectedReferenceVariantAssetKeyForEntity(entity)
  const primaryAssetKey = readText(entity.primaryAssetKey) || selectedReferenceVariantAssetKey
  return {
    ...entity,
    primaryAssetKey: primaryAssetKey || readStringArray(entity.assetKeys)[0] || '',
    assetKeys: sortReferenceValuesWithPrimary(readStringArray(entity.assetKeys), primaryAssetKey || selectedReferenceVariantAssetKey)
      .slice(0, Math.max(1, maxAssetKeys)),
  }
}

function cinematicEntityTypeBucket(entity: Record<string, unknown>) {
  const type = readText(entity.type) || readText(entity.role)
  if (['actor', 'character'].includes(type)) return 'primaryCastRefIds'
  if (['group', 'faction'].includes(type)) return 'supportingCastRefIds'
  if (['place', 'environment', 'location', 'location_spot'].includes(type)) return 'locationRefIds'
  if (['object', 'item', 'inventory_item', 'prop'].includes(type)) return 'propRefIds'
  if (['concept'].includes(type)) return 'conceptRefIds'
  return 'continuityAnchorRefIds'
}

function selectedReferenceVariantForPackedEntity(entity: Record<string, unknown>) {
  const selectedVariantKey = readText(entity.selectedReferenceVariantKey)
    || readText(asRecord(entity.metadata).selectedReferenceVariantKey)
  if (!selectedVariantKey || selectedVariantKey === 'default') return null
  const variants = Array.isArray(entity.referenceVariants)
    ? entity.referenceVariants.map(asRecord)
    : Array.isArray(asRecord(entity.metadata).referenceVariants)
      ? asRecord(entity.metadata).referenceVariants.map(asRecord)
      : []
  return variants.find((variant) => {
    const key = readText(variant.variantKey) || readText(variant.variant_key)
    return key === selectedVariantKey
  }) ?? null
}

function cinematicVariantMatchedPlanEntries(assetPack: Record<string, unknown>, prompt: string) {
  return cinematicAssetPackEntities(assetPack)
    .map((entity) => {
      const variant = selectedReferenceVariantForPackedEntity(entity)
      const score = variant ? referenceVariantMatchScore(variant, prompt) : 0
      return { entity, variant, score }
    })
    .filter((entry) => entry.variant && entry.score > 0)
    .sort((left, right) => right.score - left.score)
}

function strengthenCinematicReferencePlanWithVariantMatches(plan: Record<string, unknown>, assetPack: Record<string, unknown>, prompt: string, maxReferenceCount = 16) {
  const raw = cinematicV2ReferencePlanSchema.parse(plan)
  const allowed = new Set(cinematicAssetPackEntityKeys(assetPack))
  const selected = new Set(referencePlanKeys(raw))
  const matchedEntries = cinematicVariantMatchedPlanEntries(assetPack, prompt)
    .filter((entry) => allowed.has(readText(entry.entity.key)))
  const strengthened = {
    ...raw,
    primaryCastRefIds: [...raw.primaryCastRefIds],
    supportingCastRefIds: [...raw.supportingCastRefIds],
    locationRefIds: [...raw.locationRefIds],
    propRefIds: [...raw.propRefIds],
    conceptRefIds: [...raw.conceptRefIds],
    continuityAnchorRefIds: [...raw.continuityAnchorRefIds],
    rejectedRefs: [...raw.rejectedRefs],
  }

  for (const entry of matchedEntries) {
    if (selected.size >= Math.max(1, maxReferenceCount)) break
    const key = readText(entry.entity.key)
    if (!key || selected.has(key)) continue
    const bucket = cinematicEntityTypeBucket(entry.entity) as keyof Pick<typeof strengthened, 'primaryCastRefIds' | 'supportingCastRefIds' | 'locationRefIds' | 'propRefIds' | 'conceptRefIds' | 'continuityAnchorRefIds'>
    strengthened[bucket] = [...strengthened[bucket], key]
    selected.add(key)
  }

  const variantMatchedKeys = matchedEntries.map((entry) => readText(entry.entity.key)).filter(Boolean)
  const variantMatchedLocations = matchedEntries
    .filter((entry) => readText(entry.variant?.variantType) === 'shot_location_sheet' || readText(entry.variant?.variant_type) === 'shot_location_sheet')
    .map((entry) => readText(entry.entity.key))
    .filter(Boolean)

  return cinematicV2ReferencePlanSchema.parse({
    ...strengthened,
    rationale: [
      raw.rationale,
      variantMatchedKeys.length > 0
        ? `Variant-aware strengthening kept parent references for matched visual variants: ${variantMatchedKeys.join(', ')}.`
        : '',
      variantMatchedLocations.length > 0
        ? `Matched shot-location variants should be treated as sub-location/set references of their parent location: ${variantMatchedLocations.join(', ')}.`
        : '',
    ].filter(Boolean).join(' '),
  })
}

function filterCinematicAssetPack(assetPack: Record<string, unknown>, keys: string[], limit = 16, maxAssetKeysPerEntity = 2) {
  const keySet = new Set(keys.filter(Boolean))
  const entities = cinematicAssetPackEntities(assetPack)
    .filter((entity) => keySet.has(readText(entity.key)))
    .slice(0, Math.max(1, limit))
    .map((entity) => cloneCinematicAssetPackEntity(entity, maxAssetKeysPerEntity))
  const selectedKeys = new Set(entities.map((entity) => readText(entity.key)).filter(Boolean))
  return {
    ...assetPack,
    entities,
    selectedEntityKeys: [...selectedKeys],
    missingReferenceEntityKeys: readStringArray(assetPack.missingReferenceEntityKeys)
      .filter((key) => selectedKeys.has(key)),
  }
}

function buildFallbackCinematicV2ReferencePlan(assetPack: Record<string, unknown>, maxReferenceCount = 16) {
  const entities = cinematicAssetPackEntities(assetPack)
  const byType = (types: string[]) => entities
    .filter((entity) => types.includes(readText(entity.type) || readText(entity.role)))
    .map((entity) => readText(entity.key))
    .filter(Boolean)
  const primaryCastRefIds = byType(['actor', 'character', 'group']).slice(0, 5)
  const locationRefIds = byType(['place', 'environment', 'location', 'location_spot']).slice(0, 3)
  const propRefIds = byType(['object', 'item', 'inventory_item', 'prop']).slice(0, 4)
  const conceptRefIds = byType(['concept']).slice(0, 3)
  const selected = [...new Set([...primaryCastRefIds, ...locationRefIds, ...propRefIds, ...conceptRefIds])]
    .slice(0, Math.max(1, maxReferenceCount))
  return cinematicV2ReferencePlanSchema.parse({
    primaryCastRefIds: selected.filter((key) => primaryCastRefIds.includes(key)),
    supportingCastRefIds: [],
    locationRefIds: selected.filter((key) => locationRefIds.includes(key)),
    propRefIds: selected.filter((key) => propRefIds.includes(key)),
    conceptRefIds: selected.filter((key) => conceptRefIds.includes(key)),
    continuityAnchorRefIds: selected.filter((key) => !primaryCastRefIds.includes(key) && !locationRefIds.includes(key) && !propRefIds.includes(key) && !conceptRefIds.includes(key)),
    rejectedRefs: cinematicAssetPackEntityKeys(assetPack)
      .filter((key) => !selected.includes(key))
      .map((refId) => ({ refId, reason: 'Not selected by deterministic cinematic reference fallback.' })),
    rationale: 'Deterministic fallback selected the most likely cast, location, prop, and concept references from the sequence-scoped asset pack.',
    confidence: selected.length > 0 ? 0.55 : 0.2,
  })
}

function sanitizeCinematicV2ReferencePlan(plan: Record<string, unknown>, assetPack: Record<string, unknown>, maxReferenceCount = 16) {
  const allowed = new Set(cinematicAssetPackEntityKeys(assetPack))
  const takeValid = (values: string[]) => values.filter((key, index) => key && allowed.has(key) && values.indexOf(key) === index)
  const raw = cinematicV2ReferencePlanSchema.parse(plan)
  const ordered = [
    ...takeValid(raw.primaryCastRefIds),
    ...takeValid(raw.supportingCastRefIds),
    ...takeValid(raw.locationRefIds),
    ...takeValid(raw.propRefIds),
    ...takeValid(raw.conceptRefIds),
    ...takeValid(raw.continuityAnchorRefIds),
  ]
  const capped = new Set([...new Set(ordered)].slice(0, Math.max(1, maxReferenceCount)))
  const invalidRejected = referencePlanKeys(raw)
    .filter((key) => !allowed.has(key))
    .map((refId) => ({ refId, reason: 'Rejected because it is not in the sequence-scoped cinematic asset pack.' }))
  const unselectedRejected = cinematicAssetPackEntityKeys(assetPack)
    .filter((key) => !capped.has(key))
    .map((refId) => ({ refId, reason: 'Not needed for this cinematic-level reference plan.' }))
  const sanitized = cinematicV2ReferencePlanSchema.parse({
    ...raw,
    primaryCastRefIds: takeValid(raw.primaryCastRefIds).filter((key) => capped.has(key)),
    supportingCastRefIds: takeValid(raw.supportingCastRefIds).filter((key) => capped.has(key)),
    locationRefIds: takeValid(raw.locationRefIds).filter((key) => capped.has(key)),
    propRefIds: takeValid(raw.propRefIds).filter((key) => capped.has(key)),
    conceptRefIds: takeValid(raw.conceptRefIds).filter((key) => capped.has(key)),
    continuityAnchorRefIds: takeValid(raw.continuityAnchorRefIds).filter((key) => capped.has(key)),
    rejectedRefs: [...raw.rejectedRefs, ...invalidRejected, ...unselectedRejected]
      .filter((entry, index, entries) => entries.findIndex((candidate) => candidate.refId === entry.refId) === index),
  })
  if (referencePlanKeys(sanitized).length > 0) return sanitized
  return buildFallbackCinematicV2ReferencePlan(assetPack, maxReferenceCount)
}

function entityMentionedInShotText(entity: Record<string, unknown>, shotText: string) {
  const selectedVariant = selectedReferenceVariantForPackedEntity(entity)
  const candidates = [
    readText(entity.key),
    readText(entity.name),
    ...readStringArray(entity.aliases),
    readText(entity.selectedReferenceVariantKey),
    readText(entity.selectedReferenceVariantLabel),
    readText(selectedVariant?.variantKey ?? selectedVariant?.variant_key),
    readText(selectedVariant?.label),
    readText(selectedVariant?.summary),
    readText(selectedVariant?.guidance),
  ]
  return candidates
    .map((candidate) => normalizeComicReferenceText(candidate).replace(/_/g, ' '))
    .filter((candidate) => candidate.length > 2)
    .some((candidate) => shotText.includes(candidate))
}

function cinematicShotReferenceRepairText(shot: z.infer<typeof cinematicV2ShotSchema>) {
  return normalizeComicReferenceText([
    shot.title,
    shot.description,
    shot.action,
    shot.caption,
    shot.lighting,
    shot.mood,
    shot.storyboardPanelPrompt,
    shot.videoDirection,
    shot.continuityInputs.join(' '),
    shot.camera.framing,
    shot.camera.angle,
    shot.camera.lens,
    shot.camera.movement,
    shot.camera.screenDirectionRule,
    ...shot.dialogue.map((line) => `${line.speakerName} ${line.speakerRefId} ${line.text} ${line.emotion}`),
    ...shot.performanceBeats.map((beat) => [
      beat.characterRefId,
      beat.bodyLanguage,
      beat.facialExpression,
      beat.gaze,
      beat.gesture,
      beat.voiceEnergy,
    ].filter(Boolean).join(' ')),
  ].filter(Boolean).join(' ')).replace(/_/g, ' ')
}

function entityExactNameMatched(entity: Record<string, unknown>, value: string) {
  const normalizedValue = normalizeComicReferenceText(value).replace(/_/g, ' ')
  if (!normalizedValue) return false
  const candidates = [
    readText(entity.key),
    readText(entity.name),
    ...readStringArray(entity.aliases),
  ]
    .map((candidate) => normalizeComicReferenceText(candidate).replace(/_/g, ' '))
    .filter((candidate) => candidate.length > 1)
  return candidates.some((candidate) => {
    if (candidate === normalizedValue) return true
    const parts = candidate.split(/\s+/).filter((part) => part.length > 1)
    return parts.includes(normalizedValue)
  })
}

export function repairCinematicV2ShotPlanVisualReferences(input: {
  shotPlan: Record<string, unknown>
  assetPack: Record<string, unknown>
}) {
  const shotPlan = cinematicV2ShotPlanSchema.parse(input.shotPlan)
  const entities = cinematicAssetPackEntities(input.assetPack)
  const allowedKeys = new Set(entities.map((entity) => readText(entity.key)).filter(Boolean))
  const byKey = new Map(entities.map((entity) => [readText(entity.key), entity]).filter(([key]) => key))
  const diagnostics: string[] = []
  const actorTypes = new Set(['actor', 'character'])
  const locationTypes = new Set(['place', 'environment', 'location', 'location_spot'])
  const propTypes = new Set(['object', 'item', 'inventory_item', 'prop'])

  const repairedShots = shotPlan.shots.map((shot) => {
    const parsedShot = cinematicV2ShotSchema.parse(shot)
    const shotText = cinematicShotReferenceRepairText(parsedShot)
    const visibleCharacterRefIds = [...new Set(parsedShot.visibleCharacterRefIds.filter((key) => allowedKeys.has(key)))]
    const speakerRefIds = [...new Set(parsedShot.speakerRefIds.filter((key) => allowedKeys.has(key)))]
    const propRefIds = [...new Set(parsedShot.propRefIds.filter((key) => allowedKeys.has(key)))]
    let locationRefId = parsedShot.locationRefId && allowedKeys.has(parsedShot.locationRefId) ? parsedShot.locationRefId : null
    const matchedEntities = entities.filter((entity) => {
      const key = readText(entity.key)
      return key && entityMentionedInShotText(entity, shotText)
    })

    for (const line of parsedShot.dialogue) {
      const currentSpeaker = readText(line.speakerRefId)
      if (currentSpeaker && allowedKeys.has(currentSpeaker)) {
        if (!speakerRefIds.includes(currentSpeaker)) speakerRefIds.push(currentSpeaker)
        continue
      }
      const matchedSpeaker = entities.find((entity) => {
        const key = readText(entity.key)
        const type = readText(entity.type) || readText(entity.role)
        return key && actorTypes.has(type) && entityExactNameMatched(entity, readText(line.speakerName))
      })
      const speakerKey = matchedSpeaker ? readText(matchedSpeaker.key) : ''
      if (speakerKey && !speakerRefIds.includes(speakerKey)) {
        speakerRefIds.push(speakerKey)
        diagnostics.push(`Repaired speaker reference ${speakerKey} on ${parsedShot.id} from dialogue speaker name.`)
      }
      if (speakerKey && !visibleCharacterRefIds.includes(speakerKey)) visibleCharacterRefIds.push(speakerKey)
    }

    for (const entity of matchedEntities) {
      const key = readText(entity.key)
      const type = readText(entity.type) || readText(entity.role)
      if (!key) continue
      if (actorTypes.has(type) && !visibleCharacterRefIds.includes(key)) {
        visibleCharacterRefIds.push(key)
        diagnostics.push(`Repaired visible character reference ${key} on ${parsedShot.id} from shot text.`)
      } else if (locationTypes.has(type)) {
        const currentLocation = locationRefId ? byKey.get(locationRefId) : null
        const currentLocationMentioned = currentLocation ? entityMentionedInShotText(currentLocation, shotText) : false
        if (!locationRefId || (!currentLocationMentioned && locationRefId !== key)) {
          const previousLocation = locationRefId
          locationRefId = key
          diagnostics.push(previousLocation
            ? `Repaired location reference on ${parsedShot.id} from ${previousLocation} to ${key} based on shot text.`
            : `Repaired location reference ${key} on ${parsedShot.id} from shot text.`)
        }
      } else if (propTypes.has(type) && !propRefIds.includes(key)) {
        propRefIds.push(key)
        diagnostics.push(`Repaired prop reference ${key} on ${parsedShot.id} from shot text.`)
      }
    }

    return cinematicV2ShotSchema.parse({
      ...parsedShot,
      visibleCharacterRefIds,
      speakerRefIds,
      locationRefId,
      worldLocationRefId: readText(parsedShot.worldLocationRefId) || locationRefId,
      continuitySetId: readText(parsedShot.continuitySetId) || (locationRefId ? `set_${slugify(locationRefId)}_primary` : ''),
      continuityZoneId: readText(parsedShot.continuityZoneId),
      continuitySpotIds: readStringArray(parsedShot.continuitySpotIds),
      continuityAngleId: readText(parsedShot.continuityAngleId),
      propRefIds,
    })
  })

  return cinematicV2ShotPlanSchema.parse({
    ...shotPlan,
    shots: repairedShots,
    diagnostics: [...shotPlan.diagnostics, ...diagnostics],
  })
}

export function buildCinematicV2ShotAssetPack(input: {
  assetPack: Record<string, unknown>
  referencePlan?: Record<string, unknown> | null
  shot: Record<string, unknown>
  maxEntityCount?: number
  maxAssetKeysPerEntity?: number
}) {
  const shot = cinematicV2ShotSchema.parse(input.shot)
  const parsedReferencePlan = cinematicV2ReferencePlanSchema.safeParse(input.referencePlan ?? {})
  const referencePlan = parsedReferencePlan.success && referencePlanKeys(parsedReferencePlan.data).length > 0
    ? parsedReferencePlan.data
    : buildFallbackCinematicV2ReferencePlan(input.assetPack)
  const plannedKeys = new Set(referencePlanKeys(referencePlan))
  const byKey = new Map(cinematicAssetPackEntities(input.assetPack).map((entity) => [readText(entity.key), entity]).filter(([key]) => key))
  const shotText = normalizeComicReferenceText([
    shot.title,
    shot.description,
    shot.action,
    shot.caption,
    shot.lighting,
    shot.mood,
    shot.storyboardPanelPrompt,
    shot.videoDirection,
    shot.continuityInputs.join(' '),
    shot.camera.framing,
    shot.camera.angle,
    shot.camera.lens,
    shot.camera.movement,
    shot.camera.screenDirectionRule,
    ...shot.dialogue.map((line) => `${line.speakerName || line.speakerRefId} ${line.text} ${line.emotion}`),
    ...shot.performanceBeats.map((beat) => [
      beat.characterRefId,
      beat.bodyLanguage,
      beat.facialExpression,
      beat.gaze,
      beat.gesture,
      beat.voiceEnergy,
    ].filter(Boolean).join(' ')),
  ].filter(Boolean).join(' ')).replace(/_/g, ' ')
  const priorityKeys = [
    ...shot.speakerRefIds,
    ...shot.visibleCharacterRefIds,
    ...(shot.locationRefId ? [shot.locationRefId] : []),
    ...shot.propRefIds,
  ].filter((key) => plannedKeys.has(key) && byKey.has(key))
  const continuityKeys = referencePlan.continuityAnchorRefIds
    .filter((key) => plannedKeys.has(key) && byKey.has(key))
    .filter((key) => entityMentionedInShotText(byKey.get(key) ?? {}, shotText))
  const textMentionedKeys = [...plannedKeys]
    .filter((key) => byKey.has(key))
    .filter((key) => entityMentionedInShotText(byKey.get(key) ?? {}, shotText))
  const fallbackKeys = [
    ...referencePlan.primaryCastRefIds,
    ...referencePlan.locationRefIds,
    ...referencePlan.propRefIds,
    ...referencePlan.conceptRefIds,
  ].filter((key) => plannedKeys.has(key) && byKey.has(key))
  const directKeys = [...new Set([
    ...priorityKeys,
    ...continuityKeys,
    ...textMentionedKeys,
  ])]
  const selectedKeys = (directKeys.length > 0 ? directKeys : fallbackKeys)
    .slice(0, Math.max(1, input.maxEntityCount ?? 6))
  const shotAssetPack = filterCinematicAssetPack(input.assetPack, selectedKeys, input.maxEntityCount ?? 6, input.maxAssetKeysPerEntity ?? 2)
  return {
    ...shotAssetPack,
    shotId: shot.id,
    shotIndex: shot.index,
    shotReferenceKeys: selectedKeys,
    referencePlan,
    text: JSON.stringify(shotAssetPack, null, 2),
  }
}

function cinematicV3StoryboardGroupShots(input: {
  shotPlan: Record<string, unknown>
  storyboardGroup?: Record<string, unknown> | null
}) {
  const parsedShotPlan = cinematicV2ShotPlanSchema.safeParse(input.shotPlan)
  if (!parsedShotPlan.success) return []
  const parsedGroup = cinematicV2StoryboardGroupPlanSchema.shape.groups.element.safeParse(input.storyboardGroup ?? {})
  if (!parsedGroup.success) return parsedShotPlan.data.shots
  const groupShotIds = new Set(parsedGroup.data.shotIds)
  const matchedGroupShots = parsedShotPlan.data.shots.filter((shot) => groupShotIds.has(shot.id))
  return matchedGroupShots.length > 0 ? matchedGroupShots : parsedShotPlan.data.shots
}

function buildCinematicV3StoryboardGroupAssetPack(input: {
  assetPack: Record<string, unknown>
  shots: Record<string, unknown>[]
  maxEntityCount?: number
  maxAssetKeysPerEntity?: number
  includeSpeakerRefs?: boolean
  includePerformanceRefs?: boolean
  includeTextMentionedRefs?: boolean
}) {
  const byKey = new Map(cinematicAssetPackEntities(input.assetPack).map((entity) => [readText(entity.key), entity]).filter(([key]) => key))
  const keys: string[] = []
  const addKey = (key: string) => {
    if (key && byKey.has(key) && !keys.includes(key)) keys.push(key)
  }
  const groupTextParts: string[] = []

  input.shots.forEach((rawShot) => {
    readStringArray(rawShot.continuityAnchorIds).forEach(addKey)
    readStringArray(rawShot.continuityAnchorRefIds).forEach(addKey)
    const parsedShot = cinematicV2ShotSchema.safeParse(rawShot)
    const shot = parsedShot.success ? parsedShot.data : null
    if (shot) {
      shot.visibleCharacterRefIds.forEach(addKey)
      if (shot.locationRefId) addKey(shot.locationRefId)
      shot.propRefIds.forEach(addKey)
      if (input.includeSpeakerRefs !== false) {
        shot.speakerRefIds.forEach(addKey)
        shot.dialogue.forEach((line) => addKey(line.speakerRefId))
      }
      if (input.includePerformanceRefs !== false) {
        shot.performanceBeats.forEach((beat) => addKey(beat.characterRefId))
      }
      groupTextParts.push([
        shot.title,
        shot.description,
        shot.action,
        shot.caption,
        shot.lighting,
        shot.mood,
        shot.storyboardPanelPrompt,
        shot.videoDirection,
        ...(input.includeSpeakerRefs === false ? [] : shot.dialogue.map((line) => `${line.speakerName || line.speakerRefId} ${line.text} ${line.emotion}`)),
      ].filter(Boolean).join(' '))
      return
    }
    readStringArray(rawShot.visibleCharacterRefIds).forEach(addKey)
    const locationRefId = readText(rawShot.locationRefId)
    if (locationRefId) addKey(locationRefId)
    readStringArray(rawShot.propRefIds).forEach(addKey)
    if (input.includeSpeakerRefs !== false) readStringArray(rawShot.speakerRefIds).forEach(addKey)
    groupTextParts.push(JSON.stringify(rawShot))
  })

  if (input.includeTextMentionedRefs !== false) {
    const groupText = normalizeComicReferenceText(groupTextParts.join(' ')).replace(/_/g, ' ')
    cinematicAssetPackEntities(input.assetPack)
      .filter((entity) => entityMentionedInShotText(entity, groupText))
      .forEach((entity) => addKey(readText(entity.key)))
  }

  const selectedKeys = keys.slice(0, Math.max(0, input.maxEntityCount ?? 4))
  const groupAssetPack = filterCinematicAssetPack(
    input.assetPack,
    selectedKeys,
    Math.max(1, input.maxEntityCount ?? 4),
    input.maxAssetKeysPerEntity ?? 2,
  )
  return {
    ...groupAssetPack,
    storyboardGroupReferenceKeys: selectedKeys,
    referenceScope: 'cinematic_v3_storyboard_group',
    text: JSON.stringify(groupAssetPack, null, 2),
  }
}

function directReferenceEntityForAssetKey(assetKey: string, index: number, role = 'continuity_reference') {
  return {
    key: `direct_ref_${index + 1}_${slugify(assetKey)}`,
    name: `Reference ${index + 1}`,
    type: 'continuity_asset',
    role,
    summary: 'Selected visual reference for this generated image.',
    visualDescription: 'Use the attached reference to preserve identity, spatial layout, materials, lighting, and style continuity.',
    assetKeys: [assetKey],
    primaryAssetKey: assetKey,
    selectedReferenceAssetKey: assetKey,
    selectedReferenceVariantKey: 'selected_reference',
    selectedReferenceVariantLabel: `Reference ${index + 1}`,
    selectedReferenceVariantType: 'continuity_asset',
    referenceSelectionReason: 'Selected by the sequence animatic visual reference plan.',
  }
}

function scopeAssetPackToReferenceAssetKeys(input: {
  assetPack: Record<string, unknown>
  referenceAssetKeys: string[]
  fallbackEntities?: Record<string, unknown>[]
  referenceScope: string
  limit?: number
}) {
  const referenceAssetKeys = [...new Set(input.referenceAssetKeys.map(readText).filter(Boolean))].slice(0, Math.max(1, input.limit ?? 8))
  const fallbackEntities = (input.fallbackEntities ?? []).map(asRecord)
  if (referenceAssetKeys.length === 0) {
    return {
      ...input.assetPack,
      entities: fallbackEntities.length > 0 ? fallbackEntities : readArray(input.assetPack.entities).map(asRecord),
      scopedReferenceAssetKeys: [],
      referenceScope: input.referenceScope,
    }
  }
  const sourceEntities = [...cinematicAssetPackEntities(input.assetPack), ...fallbackEntities]
  const entities = referenceAssetKeys.map((assetKey, index) => {
    const source = sourceEntities.find((entity) => {
      const keys = [
        readText(entity.primaryAssetKey),
        readText(entity.selectedReferenceAssetKey),
        readText(entity.selectedReferenceVariantAssetKey),
        ...readStringArray(entity.assetKeys),
      ].filter(Boolean)
      return keys.includes(assetKey)
    })
    if (!source) return directReferenceEntityForAssetKey(assetKey, index)
    const cloned = cloneCinematicAssetPackEntity(source, 1)
    return {
      ...cloned,
      primaryAssetKey: assetKey,
      selectedReferenceAssetKey: assetKey,
      assetKeys: [assetKey],
      referenceSelectionReason: readText(cloned.referenceSelectionReason) || 'Selected by the sequence animatic visual reference plan.',
    }
  })
  return {
    ...input.assetPack,
    entities,
    selectedEntityKeys: entities.map((entity) => readText(entity.key)).filter(Boolean),
    scopedReferenceAssetKeys: referenceAssetKeys,
    referenceScope: input.referenceScope,
    referenceDiagnostics: readStringArray(input.assetPack.referenceDiagnostics),
  }
}

