function normalizeAnchorName(value: string) {
  return value
    .replace(/[_-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

function sequenceAnchorId(prefix: 'prop' | 'spot' | 'char', name: string, baseLocationRefId = '') {
  const base = [baseLocationRefId, name].filter(Boolean).join(' ')
  return `${prefix}_${slugify(base).slice(0, 72)}`
}

function sequenceAnimaticAtlasLayout(count: number) {
  const panelCount = Math.max(0, Math.min(9, Math.ceil(count)))
  if (panelCount <= 0) return { rows: 0, columns: 0, panelCount: 0 }
  if (panelCount === 1) return { rows: 1, columns: 1, panelCount }
  if (panelCount === 2) return { rows: 1, columns: 2, panelCount }
  if (panelCount <= 4) return { rows: 2, columns: 2, panelCount }
  if (panelCount <= 6) return { rows: 2, columns: 3, panelCount }
  return { rows: 3, columns: 3, panelCount }
}

function sequenceAnimaticAtlasImageSize(layout: { rows: number; columns: number }) {
  if (layout.rows <= 0 || layout.columns <= 0) return { width: 1024, height: 1024 }
  return {
    width: Math.max(1024, Math.min(3072, layout.columns * 768)),
    height: Math.max(1024, Math.min(3072, layout.rows * 768)),
  }
}

async function verifySequenceAnimaticAnchorCrop(input: {
  outputPath: string
  anchorId: string
  expectedWidth: number
  expectedHeight: number
  row: number
  column: number
}) {
  const [fileStat, size] = await Promise.all([
    Deno.stat(input.outputPath),
    probeImageSize(input.outputPath),
  ])
  if (!size || size.width <= 0 || size.height <= 0) {
    throw new Error(`Sequence animatic continuity crop verification failed for ${input.anchorId}: output is not a readable image.`)
  }
  if (size.width < 32 || size.height < 32) {
    throw new Error(`Sequence animatic continuity crop verification failed for ${input.anchorId}: crop is too small (${size.width}x${size.height}).`)
  }
  if (Math.abs(size.width - input.expectedWidth) > 2 || Math.abs(size.height - input.expectedHeight) > 2) {
    throw new Error(`Sequence animatic continuity crop verification failed for ${input.anchorId}: expected ${input.expectedWidth}x${input.expectedHeight}, got ${size.width}x${size.height}.`)
  }
  if (fileStat.size < 512) {
    throw new Error(`Sequence animatic continuity crop verification failed for ${input.anchorId}: output byte size is suspiciously small (${fileStat.size} bytes).`)
  }
  const signal = await runFfmpeg(['-v', 'info', '-i', input.outputPath, '-vf', 'signalstats,metadata=print', '-frames:v', '1', '-f', 'null', '-'])
  const yMin = Number(signal.stderr.match(/lavfi\.signalstats\.YMIN=([0-9.]+)/)?.[1] ?? NaN)
  const yMax = Number(signal.stderr.match(/lavfi\.signalstats\.YMAX=([0-9.]+)/)?.[1] ?? NaN)
  if (Number.isFinite(yMin) && Number.isFinite(yMax) && Math.abs(yMax - yMin) <= 1) {
    throw new Error(`Sequence animatic continuity crop verification failed for ${input.anchorId}: crop appears visually blank at row ${input.row + 1}, column ${input.column + 1}.`)
  }
  return {
    width: size.width,
    height: size.height,
    byteSize: fileStat.size,
    lumaRange: Number.isFinite(yMin) && Number.isFinite(yMax) ? Math.round((yMax - yMin) * 100) / 100 : null,
  }
}

function sequenceShotSearchText(shot: Record<string, unknown>) {
  const dialogue = (Array.isArray(shot.dialogue) ? shot.dialogue : [])
    .map((line) => `${readText(asRecord(line).speakerName)} ${readText(asRecord(line).text)}`)
    .join(' ')
  const camera = asRecord(shot.camera)
  return [
    shot.id,
    shot.title,
    shot.description,
    shot.action,
    shot.caption,
    shot.storyboardPanelPrompt,
    shot.videoDirection,
    shot.lighting,
    shot.mood,
    camera.framing,
    camera.angle,
    camera.movement,
    dialogue,
  ].map(readText).filter(Boolean).join(' ')
}

function sequenceShotPropSearchText(shot: Record<string, unknown>) {
  const dialogue = (Array.isArray(shot.dialogue) ? shot.dialogue : [])
    .map((line) => `${readText(asRecord(line).speakerName)} ${readText(asRecord(line).text)}`)
    .join(' ')
  const camera = asRecord(shot.camera)
  return [
    shot.id,
    shot.title,
    shot.description,
    shot.action,
    shot.caption,
    shot.storyboardPanelPrompt,
    shot.videoDirection,
    camera.framing,
    camera.angle,
    camera.movement,
    dialogue,
  ].map(readText).filter(Boolean).join(' ')
}

function titleFromRefLike(value: string) {
  return normalizeAnchorName(value)
    .split(' ')
    .filter(Boolean)
    .map((part) => `${part.slice(0, 1).toUpperCase()}${part.slice(1)}`)
    .join(' ')
}

